-- OUTREPD — everything the server needs, in one paste.
--
-- Generated by joining the files in `supabase/` in the order they depend on
-- each other. Paste it into the Supabase SQL editor and run it once.
-- Re-running is safe: every object is created with `if not exists`, `or
-- replace`, or dropped first.
--
-- Regenerate with:  python tool/build_install.py
--
-- Afterwards, from the app folder:
--
--   flutter test test/ladder_server_test.dart  --dart-define=...   (485 cases)
--   flutter test test/duel_server_test.dart    --dart-define=...   (a real duel)


-- ========================================================================
-- subscriptions.sql
-- ========================================================================

-- The subscription, as the server knows it.
--
-- The app keeps a paywall in front of everything, but the app is a phone in
-- somebody else's hands: a modified client can skip any screen. So the calls
-- that make a duel happen — writing a set, finding an opponent, settling —
-- also ask the server, and the server's answer comes from here.
--
-- Who has paid is written by one thing only: the `revenuecat-webhook` edge
-- function, with the service key, whenever RevenueCat reports a purchase, a
-- renewal, a cancellation or an expiry. No client can insert or update a row.
--
-- Enforcement starts switched OFF (the `paywall_enforced` row in
-- server_switches below), because until the webhook is live no row here is
-- ever written, and turning it on then would lock out every paying lifter
-- too. It is turned on with supabase/switches.sql, when the steps at the top
-- of functions/revenuecat-webhook/index.ts are done.
--
-- This file comes first in install.sql: the sets policy in schema.sql and the
-- functions in duel.sql call has_pro().

create table if not exists subscriptions (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- Whether the Pro entitlement is active, as RevenueCat last reported it.
  active boolean not null default false,
  -- When it lapses unless renewed. Null for a lifetime grant.
  expires_at timestamptz,
  product_id text,
  store text,
  updated_at timestamptz not null default now()
);

-- 'normal', 'trial' or 'intro': the period the plan is in, as RevenueCat
-- names it. Added after the table; the webhook writes it, so this has to be
-- installed before a webhook that sends it is deployed.
alter table subscriptions add column if not exists period_type text;

alter table subscriptions enable row level security;

-- A lifter may read their own row (the app does not today, but a support
-- question is answered faster when it can). Nobody may write one.
drop policy if exists "a lifter reads their own subscription" on subscriptions;
create policy "a lifter reads their own subscription"
  on subscriptions for select
  to authenticated
  using (user_id = (select auth.uid()));

-- The server's switches, one row each. A row, not a constant in a function:
-- the switch used to be `select false` written into paywall_enforced(), so
-- turning enforcement on and then pasting install.sql again for anything
-- else would have quietly turned it back off. The insert below only ever
-- adds a missing row; a value already set survives every re-install.
--
-- Row level security with no policy: nobody reads or writes these through
-- the API. They are flipped in the SQL editor — see supabase/switches.sql.
create table if not exists server_switches (
  name text primary key,
  enabled boolean not null,
  changed_at timestamptz not null default now()
);
alter table server_switches enable row level security;

insert into server_switches (name, enabled)
values ('paywall_enforced', false)
on conflict (name) do nothing;

-- Whether a duel needs Pro. Off until the webhook has been writing the
-- subscriptions table and an app version that syncs right after a purchase
-- is out — see functions/revenuecat-webhook/index.ts.
create or replace function paywall_enforced()
returns boolean
language sql
-- Stable, not immutable: an immutable function can be folded into a cached
-- plan, and then flipping the switch would not reach sessions already open.
stable
-- Definer, to read a table nobody else may.
security definer
set search_path = public
as $$
  select coalesce(
    (select enabled from server_switches where name = 'paywall_enforced'),
    false)
$$;

-- Whether [uid] may play: always, while enforcement is off; otherwise only
-- with an active, unexpired subscription. A short grace past the expiry
-- covers a renewal that the store has taken but the webhook has not yet
-- reported.
create or replace function has_pro(uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not paywall_enforced()
    or exists (
      select 1
      from subscriptions s
      where s.user_id = uid
        and s.active
        and (s.expires_at is null or s.expires_at > now() - interval '1 hour')
    )
$$;

-- Raised at the top of every call that plays a duel.
create or replace function require_pro()
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not has_pro(auth.uid()) then
    raise exception 'subscription required';
  end if;
end;
$$;

-- ========================================================================
-- schema.sql
-- ========================================================================

-- OUTREPD — the smallest schema that makes a duel real.
--
-- Three tables. A profile is who somebody is on the ladder; a set is one
-- minute of push-ups with the evidence behind the count; a duel is two sets
-- compared. Everything else the app shows — history, the board, the accuracy
-- record — is a query over these.
--
-- Two rules run through the whole file, and both exist because the client is
-- a phone in somebody else's hands:
--
--   1. **Nobody writes their own rank.** Not the tier, not the LP, not the
--      win count. Those columns are written by `settle_duel` and by nothing
--      else. A client that could write them could type itself to the top.
--   2. **A score carries its evidence.** Every set stores what the camera
--      counted *and* what the lifter confirmed, because today the lifter has
--      the last word and one day a server may need to check. Evidence cannot
--      be added to matches that are already over, so it is stored from the
--      first row.

-- ─────────────────────────────── profiles ────────────────────────────────────

create table if not exists profiles (
  id            uuid primary key references auth.users on delete cascade,
  username      text not null unique
                check (char_length(username) between 2 and 20),
  -- Null until `set_my_username` has been called once. Every account gets
  -- exactly one rename, and this is what `set_my_username` checks to know
  -- whether that one has already been spent.
  username_changed_at timestamptz,
  -- Points into the `avatars` storage bucket. Null means the drawn initial
  -- every screen already falls back to, not a broken image.
  avatar_url    text,
  country       text,
  created_at    timestamptz not null default now(),

  -- The ladder. Seven tiers of five divisions; LP runs 0..99 inside a
  -- division. `top_tier()` in ladder.sql is the same number.
  tier_idx      int  not null default 0 check (tier_idx between 0 and 6),
  div_idx       int  not null default 0 check (div_idx  between 0 and 4),
  lp            int  not null default 0 check (lp between 0 and 99),

  -- The floor: the highest tier ever held. A tier once reached is kept, so a
  -- losing streak can cost divisions and never the tier itself.
  peak_tier_idx int  not null default 0 check (peak_tier_idx between 0 and 6),

  -- Placements. Until these are done there is no rank at all, which is the
  -- point of them.
  placements_done int not null default 0 check (placements_done between 0 and 5),
  placement_wins  int not null default 0 check (placement_wins  between 0 and 5),

  wins          int not null default 0 check (wins   >= 0),
  losses        int not null default 0 check (losses >= 0),
  win_streak    int not null default 0 check (win_streak  >= 0),
  best_streak   int not null default 0 check (best_streak >= 0),

  total_reps    int not null default 0 check (total_reps >= 0),
  best_set      int not null default 0 check (best_set   >= 0),

  -- ── what this lifter has asked for ──────────────────────────────────────
  --
  -- Preferences, not ladder state, so the guard below leaves them alone: a
  -- client may write these and only these about itself.

  -- Who may be handed this account's stored sets to race.
  challengeable text not null default 'everyone'
                check (challengeable in ('everyone', 'friends', 'nobody')),

  -- Whether to appear on the boards at all, and whether the country board is
  -- one of them. Enforced in `leaderboard()` rather than filtered on the
  -- phone, because a preference a client can skip is not a preference.
  show_on_board bool not null default true,
  show_country  bool not null default true,

  -- Which of the three things that actually happen are worth being told
  -- about. Checked by the triggers in notify.sql, so a notice somebody said
  -- they did not want is never written down in the first place.
  notify_raced          bool not null default true,
  notify_friend_request bool not null default true,
  notify_friend_ok      bool not null default true,
  notify_challenged     bool not null default true,

  updated_at    timestamptz not null default now()
);

-- For a project created before the preferences above existed.
alter table profiles add column if not exists challengeable text not null
  default 'everyone';
alter table profiles drop constraint if exists profiles_challengeable_check;
alter table profiles add constraint profiles_challengeable_check
  check (challengeable in ('everyone', 'friends', 'nobody'));
alter table profiles add column if not exists show_on_board bool not null
  default true;
alter table profiles add column if not exists show_country bool not null
  default true;
alter table profiles add column if not exists notify_raced bool not null
  default true;
alter table profiles add column if not exists notify_friend_request bool
  not null default true;
alter table profiles add column if not exists notify_friend_ok bool not null
  default true;
alter table profiles add column if not exists notify_challenged bool not null
  default true;
-- A friend asking to go live (live.sql). The invite itself still arrives in
-- the app; this is only whether it buzzes the phone.
alter table profiles add column if not exists notify_live_invite bool not null
  default true;
alter table profiles add column if not exists avatar_url text;
alter table profiles add column if not exists username_changed_at timestamptz;
-- When this lifter last chose a country themselves (set_my_country). Null
-- until then: the phone's own region fills the column in, and that is not a
-- choice anybody made.
alter table profiles add column if not exists country_changed_at timestamptz;
-- Experience: one for every rep of every set, twenty for every match played
-- (count_reps_of_set below; xp_for_duel, live.sql). Only ever goes up.
alter table profiles add column if not exists xp int not null default 0;

-- The title this lifter wears beside their name, by its id in the app's list
-- (`first_blood`). Titles are earned on the phone, so all the server can check
-- is that it looks like an id; null is wearing nothing.
alter table profiles add column if not exists title text;
alter table profiles drop constraint if exists profiles_title_check;
alter table profiles add constraint profiles_title_check
  check (title is null or title ~ '^[a-z0-9_]{1,40}$');

comment on column profiles.lp is
  'Written by settle_duel only. The client cannot move its own rank.';

-- For a project created when the ladder had nine tiers.
--
-- `create table if not exists` above does nothing to a table that already
-- exists, so the narrower checks have to be applied by hand. Any account
-- sitting on a rung that no longer exists comes down to Master first — there
-- is nowhere else for it to be, and a row that violates its own constraint
-- cannot be written again by anything.
--
-- The guard trigger refuses writes to these columns, including this one, so
-- it is opened for the length of the transaction exactly the way settle_duel
-- does it.
do $$
begin
  perform set_config('outrepd.settling', 'on', true);
  update profiles
     set tier_idx      = least(tier_idx, 6),
         peak_tier_idx = least(peak_tier_idx, 6)
   where tier_idx > 6 or peak_tier_idx > 6;
  perform set_config('outrepd.settling', 'off', true);
end $$;

alter table profiles drop constraint if exists profiles_tier_idx_check;
alter table profiles add constraint profiles_tier_idx_check
  check (tier_idx between 0 and 6);
alter table profiles drop constraint if exists profiles_peak_tier_idx_check;
alter table profiles add constraint profiles_peak_tier_idx_check
  check (peak_tier_idx between 0 and 6);

-- The board reads this constantly, and always in the same order.
create index if not exists profiles_ladder_idx
  on profiles (tier_idx desc, div_idx desc, lp desc);

-- ──────────────────────────────── friend code ─────────────────────────────────

-- A short number that names an account the way a username does, without
-- being one. Usernames are already unique, so this is not for telling two
-- lifters apart — it is for adding one without having to hand over the name
-- shown on the ladder to do it.
-- Security definer because it has to see every code already taken, and a
-- lifter can only read their own row.
create or replace function generate_friend_code()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  candidate text;
begin
  loop
    candidate := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (
      select 1 from profiles where friend_code = candidate
    );
  end loop;
  return candidate;
end;
$$;

alter table profiles add column if not exists friend_code text unique;

-- Backfills any row from before this column existed, one at a time — an
-- ordinary multi-row UPDATE would hand every row the same snapshot of "codes
-- already taken" and could mint the same candidate for two rows in one go,
-- which the unique constraint would then simply refuse outright. A loop asks
-- fresh each time, the same reason settle_duel never batches a ladder change.
--
-- Guarded like the tier migration above: the guard trigger below refuses any
-- write to this column once it exists, and on a project where this has
-- already run once, it does.
do $$
declare
  r record;
begin
  perform set_config('outrepd.settling', 'on', true);
  for r in select id from profiles where friend_code is null loop
    update profiles set friend_code = generate_friend_code() where id = r.id;
  end loop;
  perform set_config('outrepd.settling', 'off', true);
end $$;

alter table profiles alter column friend_code set not null;
alter table profiles alter column friend_code set default generate_friend_code();

-- ──────────────────────────────── sets ───────────────────────────────────────

create table if not exists sets (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null references profiles on delete cascade,
  created_at    timestamptz not null default now(),

  -- The two numbers, kept apart on purpose.
  --
  -- `reps_camera` is what the counter scored. `reps` is what the lifter
  -- confirmed, and it is the one that plays. Storing only the second would
  -- throw away the only measurement of the counter this project will ever
  -- have; storing only the first would mean the app had overruled somebody
  -- about their own set.
  reps          int  not null check (reps between 0 and 300),
  reps_camera   int  not null check (reps_camera between 0 and 300),

  -- How far a typical rep travelled against this lifter's own deepest, and
  -- whether the counter's three signals agreed. Both come out of the counter
  -- and both feed the LP.
  depth         real not null default 0 check (depth between 0 and 1),
  confident     bool not null default false,

  duration_ms   int  not null check (duration_ms > 0),

  -- Set when the lifter walked out mid-round. A duel that ends this way is a
  -- loss whatever the count said at the moment they left.
  gave_up       bool not null default false,

  -- When each rep landed, in milliseconds from the start of the set.
  --
  -- This is what lets an opponent's bar move at their own pace instead of
  -- their total spread evenly across the minute. Evenly is a lie — nobody is
  -- metronomic, and the last ten seconds of a minute of push-ups are nothing
  -- like the first — and racing a lie feels like racing a progress bar.
  --
  -- Small: a hundred reps is a hundred integers, a few hundred bytes. The
  -- pose recording it is read from is nine hundred kilobytes, which is why
  -- that one is not always kept and this one always is.
  rep_times     int[] not null default '{}'
                check (array_length(rep_times, 1) is null
                       or array_length(rep_times, 1) <= 300),

  -- The pose recording, when there is one. Deliberately not always: a minute
  -- of frames is about 900 KB, so the free tier holds roughly a thousand of
  -- them. Uploaded when the counter was unsure, or when the lifter offers it.
  recording_path text,

  -- Which duel consumed this set, if any. A set is faced once.
  claimed_by    uuid,

  -- Set only for a rematch: this set is not for the open pool, it is
  -- reserved for exactly this one lifter to find with `find_targeted_set`.
  -- Null is the ordinary case and means "anyone find_opponent_set matches".
  challenge_target uuid references profiles on delete set null
);

-- For a project that already has the table from an earlier paste.
alter table sets add column if not exists rep_times int[] not null default '{}';
alter table sets add column if not exists challenge_target uuid
  references profiles on delete set null;
-- Set when the set was lifted in a live match (live.sql). It already has its
-- opponent, so it is never offered to the open pool.
alter table sets add column if not exists live_match uuid;
-- A practice minute: nobody on the other side, and nobody ever will be. Stored
-- for what it adds to the totals and to experience, never offered to the pool
-- or raced.
alter table sets add column if not exists practice boolean not null default false;

create index if not exists sets_open_idx
  on sets (profile_id, created_at desc)
  where claimed_by is null;

-- Every foreign key has an index on the side that points. Deleting an
-- account deletes or clears each row that points at it, and with no index
-- Postgres reads the whole table to find them — once for every row the
-- deletion reaches, which for a set is every duel there has ever been.
-- Partial where the column may be empty: an equality implies not null, so
-- the lookup still uses it, and the empty rows cost nothing to keep.
create index if not exists sets_challenge_target_idx
  on sets (challenge_target) where challenge_target is not null;

-- Reps are counted when the set is stored, not when it is raced.
--
-- A set is push-ups somebody did. Counting them at settle time meant the
-- challenger's reps landed and the defender's never did — their set was raced
-- *by* somebody, and nothing ever added it to their own total.
create or replace function count_reps_of_set()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform set_config('outrepd.settling', 'on', true);
  update profiles set
    total_reps = total_reps + new.reps,
    best_set   = greatest(best_set, new.reps),
    xp         = xp + new.reps
  where id = new.profile_id;
  perform set_config('outrepd.settling', 'off', true);
  return new;
end;
$$;

drop trigger if exists sets_count_reps on sets;
create trigger sets_count_reps
  after insert on sets
  for each row execute function count_reps_of_set();

-- What a minute can hold. Nobody does a push-up in under 0.3 seconds — the
-- counter itself waits 0.35 between reps — and no set the app records runs
-- past a minute and a bit. A count beyond either is not a set anybody lifted,
-- and LP is paid in reps. NOT VALID: it holds every set from here on and
-- leaves rows already stored alone.
alter table sets drop constraint if exists sets_reps_fit_the_time;
alter table sets add constraint sets_reps_fit_the_time
  check (reps * 300 <= duration_ms + 1000
         and reps_camera * 300 <= duration_ms + 1000
         and duration_ms <= 75000) not valid;

-- A set the phone sends itself. The phone says what was lifted; everything
-- else about the row is the server's to decide:
--
--   * when it was stored — "oldest first" decides whose set the pool hands
--     out next, and a date the client chose would jump the queue;
--   * that nobody has raced it yet, and that it was not part of a live match
--     — those are written by settle_duel and live.sql, never sent;
--   * who a challenge may name: a friend, or somebody this account has
--     already raced. A challenge is a notice and a push on the other phone,
--     and a stranger picked out of a search is not somebody to send one to.
--
-- And how often. A set is a minute of push-ups, so a phone sending them
-- seconds apart is not lifting them, and every set adds to the totals on the
-- profile and every challenge buzzes somebody's phone.
--
-- Runs as the caller, not as the definer: sets written by settle_duel's and
-- live.sql's own functions arrive as the database owner and pass untouched.
create or replace function guard_new_set()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  new.created_at := now();
  new.claimed_by := null;
  new.live_match := null;

  if exists (
    select 1 from sets s
     where s.profile_id = new.profile_id
       and s.created_at > now() - interval '8 seconds'
  ) or (
    select count(*) from sets s
     where s.profile_id = new.profile_id
       and s.created_at > now() - interval '1 hour'
  ) >= 40 then
    raise exception 'sets are arriving faster than anybody lifts them';
  end if;

  if new.practice and new.challenge_target is not null then
    raise exception 'a practice set challenges nobody';
  end if;

  if new.challenge_target is not null then
    if new.challenge_target = new.profile_id then
      raise exception 'cannot challenge yourself';
    end if;
    -- Both are read through the caller's own rows, which is all a lifter
    -- can see of either table: their own friendships and their own duels.
    if not exists (
      select 1 from friendships f
       where f.accepted_at is not null
         and ((f.requester = new.profile_id and f.addressee = new.challenge_target)
           or (f.addressee = new.profile_id and f.requester = new.challenge_target))
    ) and not exists (
      select 1 from duels d
       where (d.challenger = new.profile_id and d.defender = new.challenge_target)
          or (d.defender = new.profile_id and d.challenger = new.challenge_target)
    ) then
      raise exception 'a challenge goes to a friend or a past opponent';
    end if;
    if (
      select count(*) from sets s
       where s.profile_id = new.profile_id
         and s.challenge_target is not null
         and s.created_at > now() - interval '1 day'
    ) >= 15 or (
      select count(*) from sets s
       where s.profile_id = new.profile_id
         and s.challenge_target = new.challenge_target
         and s.created_at > now() - interval '1 day'
    ) >= 3 then
      raise exception 'that is enough challenges for today';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists sets_guard_new on sets;
create trigger sets_guard_new
  before insert on sets
  for each row execute function guard_new_set();

-- ──────────────────────────────── duels ──────────────────────────────────────

create table if not exists duels (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),

  challenger    uuid not null references profiles on delete cascade,
  defender      uuid not null references profiles on delete cascade,
  challenger_set uuid not null references sets on delete cascade,
  defender_set   uuid not null references sets on delete cascade,

  -- Null on a draw, which the reps allow and the ladder has to survive.
  winner        uuid references profiles on delete set null,

  -- A friend room is a real duel and not a rung. Unranked duels are recorded
  -- and pay nothing: not LP, not the win record the ladder is built on.
  ranked        bool not null default true,

  lp_challenger int not null default 0,
  lp_defender   int not null default 0,

  check (challenger <> defender)
);

create index if not exists duels_for_profile_idx
  on duels (challenger, created_at desc);
create index if not exists duels_against_profile_idx
  on duels (defender, created_at desc);
-- The foreign keys' own indexes; see sets_challenge_target_idx.
create index if not exists duels_challenger_set_idx on duels (challenger_set);
create index if not exists duels_defender_set_idx on duels (defender_set);
create index if not exists duels_winner_idx
  on duels (winner) where winner is not null;

-- ───────────────────────────── row level security ────────────────────────────

alter table profiles enable row level security;
alter table sets     enable row level security;
alter table duels    enable row level security;

-- Every policy in this project reads the caller as `(select auth.uid())`,
-- never a bare `auth.uid()`. The bare call is evaluated once per row the
-- query looks at; inside a select, Postgres works it out once per query and
-- reuses it. Same answer either way, and on a table the size `sets` and
-- `duels` will reach, the difference is the difference. Supabase's
-- performance advisor flags the bare form (auth_rls_initplan).

-- A lifter reads their own row, and only their own. Everybody else is seen
-- through the functions that draw the board, a friends list or a profile
-- card, each of which hands back the columns that screen shows and keeps the
-- rest — when somebody was last online, a country they asked to hide, the
-- notices they turned off, whether they asked to be left off the boards.
-- Every row used to be readable whole by anyone signed in, which a guest
-- account is, and which made each of those settings a request rather than a
-- rule.
drop policy if exists "profiles are public to signed-in lifters" on profiles;
drop policy if exists "a lifter reads their own profile" on profiles;
create policy "a lifter reads their own profile"
  on profiles for select
  to authenticated
  using ((select auth.uid()) = id);

drop policy if exists "a lifter creates their own profile" on profiles;
create policy "a lifter creates their own profile"
  on profiles for insert
  to authenticated
  with check ((select auth.uid()) = id);

-- The only columns a lifter may change about themselves are the ones that are
-- about them rather than about their standing. The ladder columns are locked
-- by the trigger below, because a column list in a policy cannot express
-- "these may change and those may not".
drop policy if exists "a lifter edits their own profile" on profiles;
create policy "a lifter edits their own profile"
  on profiles for update
  to authenticated
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);

create or replace function guard_ladder_columns()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- What other lifters see, and so what a client must not write around the
  -- rules for: a name that skipped set_my_username's checks and its one
  -- rename, or a picture loaded from some other server, which would learn
  -- the address of everybody who opened a board. The dashboard and the
  -- service key are not a client, so a moderator can still rename somebody.
  if current_user in ('authenticated', 'anon') then
    if (new.username is distinct from old.username
        or new.username_changed_at is distinct from old.username_changed_at)
       and current_setting('outrepd.renaming', true) is distinct from 'on' then
      raise exception 'a username changes through set_my_username only';
    end if;

    -- The country decides which country board somebody is on, and a board
    -- for a small country is one a lifter could move onto to top it. Once
    -- there it changes through set_my_country and its fourteen days. An
    -- empty one is still filled in from the phone, as it always has been.
    if (new.country is distinct from old.country
        or new.country_changed_at is distinct from old.country_changed_at)
       and old.country is not null
       and current_setting('outrepd.recountry', true) is distinct from 'on' then
      raise exception 'a country changes through set_my_country only';
    end if;

    if new.avatar_url is distinct from old.avatar_url
       and new.avatar_url is not null
       and new.avatar_url !~ (
         '^https://[A-Za-z0-9.-]+/storage/v1/object/public/avatars/'
         || new.id::text || '/photo\.jpg(\?v=[0-9]+)?$') then
      raise exception 'avatar_url must be this account''s own uploaded photo';
    end if;
  end if;

  -- settle_duel runs as the definer and sets this for the length of its
  -- transaction. Anything else touching these columns is a client trying to
  -- write its own rank.
  if current_setting('outrepd.settling', true) = 'on' then
    return new;
  end if;

  if new.tier_idx        is distinct from old.tier_idx
  or new.div_idx         is distinct from old.div_idx
  or new.lp              is distinct from old.lp
  or new.peak_tier_idx   is distinct from old.peak_tier_idx
  or new.wins            is distinct from old.wins
  or new.losses          is distinct from old.losses
  or new.win_streak      is distinct from old.win_streak
  or new.best_streak     is distinct from old.best_streak
  or new.placements_done is distinct from old.placements_done
  or new.placement_wins  is distinct from old.placement_wins
  or new.total_reps      is distinct from old.total_reps
  or new.best_set        is distinct from old.best_set
  or new.xp              is distinct from old.xp then
    raise exception 'rank and record are settled by the server, not the client';
  end if;

  -- A code that a lifter could rewrite is a code somebody could hand out,
  -- have declined, and then mint a fresh one to try again under. It is
  -- assigned once, the same way an id is.
  if new.friend_code is distinct from old.friend_code then
    raise exception 'friend_code is assigned by the server, not the client';
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profiles_guard_ladder on profiles;
create trigger profiles_guard_ladder
  before update on profiles
  for each row execute function guard_ladder_columns();

-- Names nobody gets to wear on a board. The stores ask an app with names that
-- strangers see for a way to keep abuse from being posted at all, not only a
-- way to report it afterwards.
--
-- Whole words that are abuse in any name they appear in, in English and in the
-- Egyptian and Gulf spellings that turn up in Latin letters, plus the names
-- that would pass for the app itself. Short fragments that are also inside
-- ordinary words ("anal" in "analyst", "cock" in "peacock") are left out on
-- purpose: refusing somebody's real name is worse than missing a rare one,
-- and reports catch what this does not. Digits that stand in for letters are
-- read as those letters first, so "b1tch" is "bitch".
create or replace function username_not_allowed(name text)
returns boolean
language sql
immutable
set search_path = public
as $$
  select translate(lower(coalesce(name, '')), '013457@$', 'oieastas')
      ~ ('(fuck|cunt|nigg|faggot|whore|slut|bitch|pussy|porn|'
         'dildo|penis|vagina|hitler|retard|motherf|'
         'sharmoot|sharmout|sharmuta|kosom|kossom|kusom|kosomak|khawal|'
         'metnak|mitnak|'
         'outrepd|admin|moderator|official)')
    or lower(coalesce(name, '')) ~ '(شرموط|متناك|كسم|عرص|منيوك)';
$$;

-- A profile starts where everybody starts. The update guard above keeps a
-- client from writing its own rank, but nothing stopped the first insert
-- from arriving already a Master with a thousand wins, or with a name or a
-- picture the rules above would have refused.
create or replace function guard_new_profile()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  new.tier_idx        := 0;
  new.div_idx         := 0;
  new.lp              := 0;
  new.peak_tier_idx   := 0;
  new.placements_done := 0;
  new.placement_wins  := 0;
  new.wins            := 0;
  new.losses          := 0;
  new.win_streak      := 0;
  new.best_streak     := 0;
  new.total_reps      := 0;
  new.best_set        := 0;
  new.xp              := 0;
  new.friend_code     := generate_friend_code();
  new.username_changed_at := null;
  new.avatar_url      := null;
  new.title           := null;
  new.created_at      := now();

  -- Renamed rather than refused: refusing would leave a brand-new lifter
  -- with no account and no idea why. The one rename is still theirs to spend.
  --
  -- The same letters set_my_username allows, plus the underscore the app's
  -- own first name for a guest has in it. Anything else is a name nobody
  -- could type into a search — or one built to look like somebody else's
  -- out of characters that only resemble theirs.
  if username_not_allowed(new.username)
     or new.username !~ '^[A-Za-z0-9_]{2,20}$' then
    new.username := 'lifter' || substr(replace(new.id::text, '-', ''), 1, 6);
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_new on profiles;
create trigger profiles_guard_new
  before insert on profiles
  for each row execute function guard_new_profile();

-- A set belongs to the lifter who did it. They may write it once and read
-- their own; everyone can read a set that a duel has already joined them to.
-- Only a subscriber writes one (has_pro, in subscriptions.sql — always true
-- until enforcement is switched on there).
drop policy if exists "a lifter writes their own sets" on sets;
create policy "a lifter writes their own sets"
  on sets for insert
  to authenticated
  with check ((select auth.uid()) = profile_id and has_pro((select auth.uid())));

drop policy if exists "a lifter reads their own sets" on sets;
create policy "a lifter reads their own sets"
  on sets for select
  to authenticated
  using ((select auth.uid()) = profile_id);

-- Duels are readable by the two people in them, and by nobody else.
drop policy if exists "a lifter reads their own duels" on duels;
create policy "a lifter reads their own duels"
  on duels for select
  to authenticated
  using ((select auth.uid()) = challenger or (select auth.uid()) = defender);

-- Nothing inserts into duels directly. settle_duel does it, as the definer.

-- ──────────────────────────────── blocks ─────────────────────────────────────

-- Somebody you want nothing further to do with.
--
-- One row, one direction: you blocked them. It is read from both ends
-- wherever it is enforced, because blocking has to work whichever of the two
-- opens the app — but only one of you gets to undo it, and they are not told
-- it happened.
create table if not exists blocks (
  blocker    uuid not null references profiles on delete cascade,
  blocked    uuid not null references profiles on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker, blocked),
  check (blocker <> blocked)
);

create index if not exists blocks_blocked_idx on blocks (blocked);

alter table blocks enable row level security;

-- Only the blocker sees the row. Showing it to the blocked person would
-- tell them, which is the one thing a block must not do.
drop policy if exists "a lifter reads their own blocks" on blocks;
create policy "a lifter reads their own blocks"
  on blocks for select
  to authenticated
  using ((select auth.uid()) = blocker);

drop policy if exists "a lifter blocks in their own name" on blocks;
create policy "a lifter blocks in their own name"
  on blocks for insert
  to authenticated
  with check ((select auth.uid()) = blocker);

drop policy if exists "a lifter unblocks their own" on blocks;
create policy "a lifter unblocks their own"
  on blocks for delete
  to authenticated
  using ((select auth.uid()) = blocker);

-- ──────────────────────────────────── mutes ───────────────────────────────────

-- Somebody whose stored sets you would rather not be offered.
--
-- Lighter than a block: it says nothing to the friendship, the profile is
-- still visible, and they are never told. One row, one direction, checked
-- only from the muter's own side — muting somebody stops them turning up as
-- an opponent for you; it says nothing about whether your own sets still
-- turn up for them.
create table if not exists mutes (
  muter      uuid not null references profiles on delete cascade,
  muted      uuid not null references profiles on delete cascade,
  created_at timestamptz not null default now(),
  primary key (muter, muted),
  check (muter <> muted)
);

create index if not exists mutes_muted_idx on mutes (muted);

alter table mutes enable row level security;

-- Only the muter sees the row, same as a block: it must not be a way to find
-- out somebody muted you.
drop policy if exists "a lifter reads their own mutes" on mutes;
create policy "a lifter reads their own mutes"
  on mutes for select
  to authenticated
  using ((select auth.uid()) = muter);

drop policy if exists "a lifter mutes in their own name" on mutes;
create policy "a lifter mutes in their own name"
  on mutes for insert
  to authenticated
  with check ((select auth.uid()) = muter);

drop policy if exists "a lifter unmutes their own" on mutes;
create policy "a lifter unmutes their own"
  on mutes for delete
  to authenticated
  using ((select auth.uid()) = muter);

-- ──────────────────────────────── reports ────────────────────────────────────

-- Somebody saying something is wrong.
--
-- Write-only from the app's side: a reporter may file one and can never read
-- the pile back, because the pile is about other people. Nothing in the app
-- reads this table at all — it is read by whoever is looking at reports, in
-- the dashboard.
create table if not exists reports (
  id          uuid primary key default gen_random_uuid(),
  reporter    uuid not null references profiles on delete cascade,
  reported    uuid references profiles on delete set null,
  created_at  timestamptz not null default now(),

  reason text not null
         check (reason in ('cheating', 'harassment', 'content',
                           'impersonation', 'other')),

  -- Optional, and capped: a free text box with no limit is a free text box
  -- somebody will paste a novel into.
  details text not null default '' check (char_length(details) <= 1000)
);

create index if not exists reports_reported_idx
  on reports (reported, created_at desc);
create index if not exists reports_reporter_idx on reports (reporter);

alter table reports enable row level security;

drop policy if exists "a lifter files their own reports" on reports;
create policy "a lifter files their own reports"
  on reports for insert
  to authenticated
  with check ((select auth.uid()) = reporter);

-- Each report emails whoever answers them (functions/report-alert), so an
-- account that files them in a loop fills an inbox. Past ten a day, or a
-- second one about the same account the same day, the report is quietly not
-- stored: the reporter sees it go through, and the inbox sees nothing new.
-- Runs as the caller, who can see nothing of this table, so the counting
-- goes through count_my_reports below.
create or replace function count_my_reports(about uuid)
returns table (today int, about_them int)
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::int,
         (count(*) filter (where r.reported = about))::int
    from reports r
   where r.reporter = auth.uid()
     and r.created_at > now() - interval '1 day';
$$;

revoke all on function count_my_reports(uuid) from public, anon;
grant execute on function count_my_reports(uuid) to authenticated;

create or replace function guard_new_report()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  counted record;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  new.created_at := now();
  -- Set by report-alert once it has emailed about this report (push.sql).
  -- A report that arrived already marked would never be emailed about.
  new.alerted_at := null;
  select * into counted from count_my_reports(new.reported);
  if counted.today >= 10 or counted.about_them >= 1 then
    return null;
  end if;
  return new;
end;
$$;

drop trigger if exists reports_guard_new on reports;
create trigger reports_guard_new
  before insert on reports
  for each row execute function guard_new_report();

-- Deliberately no select policy. Filing a report does not entitle anybody to
-- read reports, including their own — there is nothing useful in reading it
-- back, and a readable pile is one more thing to leak.

-- ─────────────────────────────── how often ─────────────────────────────────────

-- Things a lifter does that land on somebody else's phone or in somebody's
-- inbox — a friend request, a live invite, an emailed export — and so must
-- not be repeatable without end. One row each time one goes through; nothing
-- reads or writes this table but within_rate below.
create table if not exists rate_events (
  profile_id uuid not null references profiles on delete cascade,
  kind       text not null,
  target     uuid,
  at         timestamptz not null default now()
);

-- A key of its own. Nothing looks a row up by it; it is there because
-- Postgres replication and Supabase's realtime need one on every table, and
-- deleting old rows is cheaper with one.
alter table rate_events
  add column if not exists id bigint generated always as identity primary key;

create index if not exists rate_events_idx
  on rate_events (profile_id, kind, at desc);

alter table rate_events enable row level security;

-- Whether the caller may do [what] once more: fewer than [most] in the last
-- [per] — counted toward [toward] alone when one is given. Counts this one
-- if so. Only the server's own functions call it; nothing a phone can reach.
create or replace function within_rate(
  what text,
  per interval,
  most int,
  toward uuid default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  used int;
begin
  if auth.uid() is null then
    return false;
  end if;
  delete from rate_events
   where profile_id = auth.uid() and at < now() - interval '2 days';
  select count(*) into used from rate_events
   where profile_id = auth.uid()
     and kind = what
     and at > now() - per
     and (toward is null or target = toward);
  if used >= most then
    return false;
  end if;
  insert into rate_events (profile_id, kind, target)
  values (auth.uid(), what, toward);
  return true;
end;
$$;

revoke all on function within_rate(text, interval, int, uuid)
  from public, anon, authenticated;

-- ──────────────────────────────── avatars ─────────────────────────────────────

-- The photo behind `profiles.avatar_url`.
--
-- Public read, because an avatar is drawn on everyone else's screen too — the
-- leaderboard, a stranger's profile, a shared card. Public storage is not
-- public data: nothing here is a photo unless a lifter chose to upload one,
-- and the path convention below is what keeps one account from overwriting
-- another's.
--
-- Path convention: `<account id>/photo`. `storage.foldername(name)` splits
-- that on `/`, so its first element is the id a write has to match.
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do nothing;

-- A photo, and a small one: the phone sends an 800-pixel JPEG. Without this
-- the public bucket would host anything any account cared to put in it.
update storage.buckets
   set file_size_limit = 5242880,
       allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']
 where id = 'avatars';

-- Drawn from the bucket's public address, which serves any photo to anybody
-- holding its link without asking the policies at all. What a policy here
-- controls is listing the bucket through the API — every account with a
-- photo, by id — so it reaches the lifter's own file and nothing else. The
-- upload replaces that file in place, and replacing needs to see it.
drop policy if exists "avatars are public to read" on storage.objects;
drop policy if exists "a lifter sees their own avatar file" on storage.objects;
create policy "a lifter sees their own avatar file"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'avatars'
    and name = (select auth.uid())::text || '/photo.jpg'
  );

-- One file per account, at the one path the app writes: `<id>/photo.jpg`.
-- The folder alone was the rule before, which let an account fill its folder
-- with as many public files as it liked, under any names — free hosting on
-- this project's bill and its domain.
drop policy if exists "a lifter uploads their own avatar" on storage.objects;
create policy "a lifter uploads their own avatar"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'avatars'
    and name = (select auth.uid())::text || '/photo.jpg'
  );

drop policy if exists "a lifter replaces their own avatar" on storage.objects;
create policy "a lifter replaces their own avatar"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'avatars'
    and name = (select auth.uid())::text || '/photo.jpg'
  )
  with check (
    bucket_id = 'avatars'
    and name = (select auth.uid())::text || '/photo.jpg'
  );

drop policy if exists "a lifter deletes their own avatar" on storage.objects;
create policy "a lifter deletes their own avatar"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- ========================================================================
-- ladder.sql
-- ========================================================================

-- The ladder arithmetic, server side.
--
-- This is a twin of `lib/ranking.dart`, and twins drift. The app computes the
-- same numbers to show them before and after a round; the server computes them
-- to *apply* them, because a client that could apply its own LP could type
-- itself to the top of the board.
--
-- `test/ladder_vectors.json` is generated from the Dart implementation and
-- replayed against these functions (`supabase/ladder_test.sql`). If the two
-- ever disagree the test says which case and by how much — which is the only
-- way this stays honest, because nothing else in the system would notice.

-- ───────────────────────────── the shape of a rank ───────────────────────────

-- Nine tiers of five divisions. Divisions climb V → I, so a higher div_idx is
-- better, and LP runs 0..99 inside one.
create or replace function top_division() returns int
  language sql immutable set search_path = public as $$ select 4 $$;

-- Seven tiers, Iron to Master. It was nine: Mythic and Legend sat above
-- Master until the crest artwork settled at seven, and the app's own
-- `kTiers` is the other half of this number. They have to move together or
-- the server will hand out a rank the app cannot draw.
create or replace function top_tier() returns int
  language sql immutable set search_path = public as $$ select 6 $$;

-- The rung somebody is standing on, counted from the bottom, starting at 1.
create or replace function ladder_level(tier_idx int, div_idx int)
returns int
language sql immutable
set search_path = public
as $$
  select least(greatest(tier_idx, 0), top_tier()) * (top_division() + 1)
       + least(greatest(div_idx, 0), top_division())
       + 1;
$$;

-- ───────────────────────────── what a duel pays ──────────────────────────────

-- Exactly the gap in reps, signed by who actually won. `won` and the reps
-- normally agree; they can only split when somebody walks out while still
-- ahead, which stays a loss regardless of the count at the moment of
-- quitting — a loss must never pay a gain. No tier, no form, no cap
-- otherwise: a blowout is worth exactly what it was.
--
-- The first version took tiers and form as well. A different argument list
-- is a different function to Postgres, so `or replace` left that one behind
-- on a database the first installer was pasted into; it is dropped by name.
drop function if exists lp_for(boolean, int, int, int, int, boolean, boolean);
create or replace function lp_for(won boolean, your_reps int, their_reps int)
returns int
language sql
immutable
set search_path = public
as $$
  select case when won then abs(your_reps - their_reps)
              else -abs(your_reps - their_reps) end;
$$;

-- The same, weighed by who it was against: ten percent more or less for each
-- division between the two, up to half again or half as much. Beating
-- somebody above you pays more and losing to them costs less; the other way
-- round, less and more. Level with each other, it is the rep gap exactly.
-- Whole LP, rounded half up — the app's lpFor does the same arithmetic.
create or replace function lp_for(
  won boolean, your_reps int, their_reps int, your_level int, their_level int
)
returns int
language sql
immutable
set search_path = public
as $$
  select (case when won then 1 else -1 end)
       * ((abs(your_reps - their_reps)
           * (10 + (case when won then 1 else -1 end)
                 * greatest(-5, least(5, coalesce(their_level - your_level, 0))))
           + 5) / 10);
$$;

-- ───────────────────────── applying it to a rank ─────────────────────────────

-- Carries a change through as many promotions or demotions as it earns, and
-- holds the floor: a tier once reached cannot be lost.
create or replace function apply_lp(
  from_tier int,
  from_div int,
  from_lp int,
  delta int,
  floor_tier int
)
returns table (tier_idx int, div_idx int, lp int)
language plpgsql
immutable
set search_path = public
as $$
declare
  t int := from_tier;
  d int := from_div;
  p int := from_lp + delta;
begin
  while p >= 100 loop
    if t >= top_tier() and d >= top_division() then
      -- Nothing above this. LP stops rather than rolling over into a tier that
      -- does not exist.
      p := 99;
      exit;
    end if;
    p := p - 100;
    if d < top_division() then
      d := d + 1;
    else
      t := t + 1;
      d := 0;
    end if;
  end loop;

  while p < 0 loop
    if d = 0 and t <= floor_tier then
      p := 0;
      exit;
    end if;
    p := p + 100;
    if d > 0 then
      d := d - 1;
    else
      t := t - 1;
      d := top_division();
    end if;
  end loop;

  return query select t, d, p;
end;
$$;

-- ───────────────────────────── where placements land ─────────────────────────

-- Everybody starts in the same place. `wins` stays in the signature so a
-- caller from before the change still finds the function.
create or replace function placement_rank(wins int)
returns table (tier_idx int, div_idx int, lp int)
language sql
immutable
set search_path = public
as $$
  -- The twin of `placementRank` in `lib/ranking.dart`. One duel places an
  -- account, and it lands at the bottom whatever the result: Iron V with no
  -- LP. A single result says nothing about a lifter, so it decides nothing
  -- but that the climb has begun. (Until 1.1.4 five duels placed an account
  -- anywhere from Iron III to Silver I by how many were won.)
  select 0, 0, 0;
$$;

-- ========================================================================
-- social.sql
-- ========================================================================

-- OUTREPD — the people you know.
--
-- One table and four calls. A friendship is a single row rather than two
-- mirrored ones, because two rows can disagree: accept one and not the other
-- and the app has a friend who does not have you back.
--
-- The row is keyed on (requester, addressee) and read from both ends, so
-- "who asked" survives — it is the difference between an invitation waiting
-- on you and one waiting on them, and the screen has to say which.
--
-- What is deliberately NOT here:
--
--   * A friend cannot see anything they could not already see. Profiles were
--     public to signed-in lifters before this file existed; being friends
--     adds the head-to-head, which is read out of duels the two already
--     played against each other.
--   * No presence service. "Online" is `last_seen` within a few minutes,
--     written by the app when it opens. It costs one column and one update
--     instead of a socket per lifter, and the answer it gives — "around
--     recently" — is the one the screen actually needs.

-- ──────────────────────────────── last seen ──────────────────────────────────

-- When this account last had the app open.
--
-- Not guarded like the ladder columns: there is nothing to gain by lying
-- about it, and it is the one thing on a profile a client legitimately owns.
alter table profiles add column if not exists
  last_seen timestamptz not null default now();

-- "Who has had the app open in the last few minutes" (live_online in
-- live.sql, asked every few seconds by everybody searching): the few rows at
-- the recent end, instead of every profile there is.
create index if not exists profiles_last_seen_idx on profiles (last_seen);

-- ─────────────────────────────── friendships ─────────────────────────────────

create table if not exists friendships (
  requester   uuid not null references profiles on delete cascade,
  addressee   uuid not null references profiles on delete cascade,
  created_at  timestamptz not null default now(),

  -- Null while the request is still waiting. A status column would need a
  -- check constraint and could hold 'accepted' with no date; this cannot.
  accepted_at timestamptz,

  primary key (requester, addressee),

  -- Nobody is their own friend, and the ladder would have to decide what a
  -- duel against yourself pays.
  check (requester <> addressee)
);

-- Both directions get an index: every query here asks "who is this person to
-- me", and half of those arrive from the other end of the row.
create index if not exists friendships_addressee_idx
  on friendships (addressee, accepted_at);
create index if not exists friendships_requester_idx
  on friendships (requester, accepted_at);

alter table friendships enable row level security;

-- A row is visible to the two people in it and to nobody else. A friends
-- list is not public information, and who asked whom is less so.
drop policy if exists "a lifter reads their own friendships" on friendships;
create policy "a lifter reads their own friendships"
  on friendships for select
  to authenticated
  using ((select auth.uid()) = requester or (select auth.uid()) = addressee);

-- No insert and no update from the phone: asking goes through
-- request_friend_with and answering through answer_friend, both below. The
-- table used to take both directly, as long as the caller's own id was on
-- the row — which let a phone write a request that arrived already accepted,
-- skip the block check on the way, or, holding a request, rewrite who it was
-- from and become friends with somebody who never asked.
drop policy if exists "a lifter asks in their own name" on friendships;
drop policy if exists "only the asked may answer" on friendships;

-- Either side can end it, and either side can withdraw a request that has
-- not been answered.
drop policy if exists "either side may end it" on friendships;
create policy "either side may end it"
  on friendships for delete
  to authenticated
  using ((select auth.uid()) = requester or (select auth.uid()) = addressee);

-- ──────────────────────────────── asking ─────────────────────────────────────

-- Everything asking somebody shares once the target's id is known — only how
-- that id was found (by name, by code) differs between the two functions
-- below. Kept as one body so a rule about asking (blocked, already asked you,
-- already friends) is a rule in one place instead of two copies drifting
-- apart the next time either changes.
--
-- `security definer`, for one reason: it has to see a block made *against*
-- the caller, and the blocks policy deliberately shows a row only to whoever
-- made it. Every write below still names `auth.uid()` explicitly, so the
-- extra rights buy the check and nothing else.
create or replace function request_friend_with(them uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  theirs friendships;
begin
  if them = auth.uid() then
    return 'that is you';
  end if;

  -- Blocked, either way round. The same answer as a name that does not
  -- exist, deliberately: telling somebody they have been blocked is the one
  -- thing a block is supposed not to do, and an error that says "blocked"
  -- tells them.
  if exists (
    select 1 from blocks b
    where (b.blocker = auth.uid() and b.blocked = them)
       or (b.blocker = them and b.blocked = auth.uid())
  ) then
    return 'no such lifter';
  end if;

  -- They already asked you. Asking back is the same thing as saying yes, and
  -- making somebody find the request screen to agree to what they just asked
  -- for is a worse app.
  --
  -- Tested with `found` rather than `theirs is not null`: on a composite,
  -- IS NOT NULL means *every* field is filled, and a pending row always has
  -- a null accepted_at — so the obvious spelling would silently miss exactly
  -- the case this branch exists for.
  select * into theirs from friendships
   where requester = them and addressee = auth.uid();
  if found then
    if theirs.accepted_at is null then
      update friendships set accepted_at = now()
       where requester = them and addressee = auth.uid();
    end if;
    return 'friends';
  end if;

  -- Already asked, or already friends: nothing new to send.
  if exists (
    select 1 from friendships
     where requester = auth.uid() and addressee = them
  ) then
    return 'asked';
  end if;

  -- Each request is a notice and a push on their phone. Withdrawn and sent
  -- again, it is another one, so how often is counted: a few times a day to
  -- any one lifter, and forty new people a day in all. Past that the answer
  -- reads the same as a request that went — nothing is sent.
  if not within_rate('friend_request_to', interval '1 day', 3, them)
     or not within_rate('friend_request', interval '1 day', 40) then
    return 'asked';
  end if;

  insert into friendships (requester, addressee)
  values (auth.uid(), them)
  on conflict (requester, addressee) do nothing;

  return 'asked';
end;
$$;

-- Send a friend request, by name.
--
-- By name because that is what somebody has: you know what your friend calls
-- themselves, not their uuid. Returns the state the pair ended up in, so the
-- app can tell "asked" from "you are now friends" without asking again.
create or replace function request_friend(their_name text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  them uuid;
begin
  -- Case-insensitive, as find_lifters is: usernames keep the case they were
  -- typed in, and nobody remembers whether a friend capitalised theirs.
  select id into them from profiles
   where lower(username) = lower(trim(their_name));
  if them is null then
    return 'no such lifter';
  end if;
  return request_friend_with(them);
end;
$$;

-- Send a friend request, by their #code instead of their name.
--
-- The code exists so adding somebody never requires the name shown on the
-- ladder — see the comment on the friend_code column in schema.sql. A
-- leading '#' is accepted and stripped rather than required, since the
-- client shows the code with one but the stored value never has it.
create or replace function request_friend_by_code(code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  them uuid;
  cleaned text := trim(leading '#' from trim(code));
begin
  select id into them from profiles where friend_code = cleaned;
  if them is null then
    return 'no such lifter';
  end if;
  return request_friend_with(them);
end;
$$;

-- Answer a request that is waiting on you.
--
-- Declining deletes the row rather than marking it: a declined request that
-- lingers is a record of a small rejection kept on a server forever, and it
-- would also stop them ever asking again.
-- Security definer, since nothing on the phone may update the table itself;
-- every write here names the caller as the one who was asked.
create or replace function answer_friend(their_id uuid, accept boolean)
returns text
language plpgsql
security definer
set search_path = public
as $$
begin
  if accept then
    update friendships set accepted_at = now()
     where requester = their_id and addressee = auth.uid()
       and accepted_at is null;
    return case when found then 'friends' else 'nothing to answer' end;
  end if;

  delete from friendships
   where requester = their_id and addressee = auth.uid()
     and accepted_at is null;
  return 'declined';
end;
$$;

-- Stop being friends, without blocking. Either of the two may; the other is
-- not told, and nothing stops either asking again. Runs as the caller: the
-- delete policy on friendships ("either side may end it") is the rule.
create or replace function remove_friend(their_id uuid)
returns text
language plpgsql
set search_path = public
as $$
begin
  delete from friendships
   where accepted_at is not null
     and ((requester = auth.uid() and addressee = their_id)
       or (requester = their_id and addressee = auth.uid()));
  return case when found then 'removed' else 'not friends' end;
end;
$$;

-- ──────────────────────────────── reading ────────────────────────────────────

-- Everybody this account is actually friends with, and what stands between
-- them.
--
-- The head-to-head is the reason a row is worth tapping. A rank says how good
-- somebody is in general; "0W 4L against you" is a score to settle. It is
-- counted out of ranked *and* friend duels, because a duel that happened
-- happened — the ladder ignores friend rooms, a grudge does not.
--
-- Dropped first: Postgres refuses `create or replace` when a table-returning
-- function's column set changes shape (adding avatar_url did), and fails
-- with a "cannot change return type" error that names DROP as the fix.
drop function if exists my_friends();
create or replace function my_friends()
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  last_seen timestamptz,
  wins_vs_you int,
  losses_vs_you int,
  avatar_url text,
  xp int
)
language sql
stable
security definer
set search_path = public
as $$
  with mine as (
    select case when f.requester = auth.uid() then f.addressee
                else f.requester end as friend_id
      from friendships f
     where f.accepted_at is not null
       and (f.requester = auth.uid() or f.addressee = auth.uid())
  )
  select p.id,
         p.username,
         p.tier_idx,
         p.div_idx,
         p.lp,
         p.placements_done,
         p.last_seen,
         -- Duels are readable only by the two people in them, so this counts
         -- exactly the ones the caller was part of without needing to say so.
         coalesce(count(*) filter (where d.winner = p.id), 0)::int,
         coalesce(count(*) filter (where d.winner = auth.uid()), 0)::int,
         p.avatar_url,
         p.xp
    from mine
    join profiles p on p.id = mine.friend_id
    left join duels d
      on (d.challenger = auth.uid() and d.defender = p.id)
      or (d.defender = auth.uid() and d.challenger = p.id)
   group by p.id, p.username, p.tier_idx, p.div_idx, p.lp,
            p.placements_done, p.last_seen, p.avatar_url, p.xp
   order by p.last_seen desc;
$$;

-- Requests waiting on an answer from this account, oldest first — with
-- enough about whoever asked (photo, rank, best set, record) to decide on,
-- rather than a bare name.
--
-- Dropped first: adding columns changes the table it returns, which
-- `create or replace` refuses.
drop function if exists friend_requests();
create or replace function friend_requests()
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  asked_at timestamptz,
  placements_done int,
  best_set int,
  wins int,
  losses int,
  avatar_url text
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, f.created_at,
         p.placements_done, p.best_set, p.wins, p.losses, p.avatar_url
    from friendships f
    join profiles p on p.id = f.requester
   where f.addressee = auth.uid()
     and f.accepted_at is null
   order by f.created_at;
$$;

-- Usernames keep whoever's case they were typed in (see set_my_username), so
-- finding one by name is always a case-insensitive comparison. A plain index
-- on `username` cannot serve that — Postgres only uses a btree for LIKE-style
-- matching when the indexed expression matches the comparison byte-for-byte,
-- collation included. This is the expression find_lifters() below actually
-- compares against, so it is the one that keeps every search a fast prefix
-- lookup instead of a sequential scan once there are many accounts to scan.
create index if not exists profiles_username_prefix_idx
  on profiles (lower(username) text_pattern_ops);

-- Find somebody to add, by the start of their name.
--
-- Capped hard and never open-ended: this is the one call that hands back
-- people the caller has no relationship with, so it answers a specific
-- question ("is my friend on here under this name") rather than enumerating
-- the userbase. A blank query returns nothing at all.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists find_lifters(text, int);
create or replace function find_lifters(query text, limit_to int default 10)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  placements_done int,
  avatar_url text
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, p.placements_done,
         p.avatar_url
    from profiles p
   where length(trim(query)) >= 2
     and p.id <> auth.uid()
     -- Same comparison as profiles_username_prefix_idx above, on purpose:
     -- ilike would read identically but plans as a sequential scan, because
     -- nothing ties it back to that index.
     --
     -- What was typed is matched as written. In a like pattern `_` stands
     -- for any one character and `%` for any run of them, so a name with an
     -- underscore in it found its neighbours too, and a search for "%%"
     -- listed whoever came first alphabetically. Both are escaped, and the
     -- escape character itself before them.
     and lower(p.username) like
         replace(replace(replace(lower(trim(query)),
           '\', '\\'), '%', '\%'), '_', '\_') || '%'
     -- Somebody blocked, in either direction, is simply not there. A search
     -- that still turns them up is a block that only half works.
     and not exists (
       select 1 from blocks b
       where (b.blocker = auth.uid() and b.blocked = p.id)
          or (b.blocker = p.id and b.blocked = auth.uid())
     )
   order by p.username
   limit least(greatest(limit_to, 1), 25);
$$;

-- ──────────────────────────────── blocking ───────────────────────────────────

-- Block somebody, and end whatever was between you.
--
-- The friendship goes with it. Staying friends with somebody you have just
-- blocked is a state nothing in the app could draw honestly, and it would
-- leave them on your friends list where they can see you are still there.
create or replace function block_lifter(their_id uuid)
returns text
language plpgsql
set search_path = public
as $$
begin
  if their_id = auth.uid() then
    return 'that is you';
  end if;

  insert into blocks (blocker, blocked)
  values (auth.uid(), their_id)
  on conflict (blocker, blocked) do nothing;

  delete from friendships
   where (requester = auth.uid() and addressee = their_id)
      or (requester = their_id and addressee = auth.uid());

  return 'blocked';
end;
$$;

create or replace function unblock_lifter(their_id uuid)
returns text
language plpgsql
set search_path = public
as $$
begin
  delete from blocks where blocker = auth.uid() and blocked = their_id;
  return 'unblocked';
end;
$$;

-- Who this account has blocked, newest first. Only ever their own list.
create or replace function my_blocks()
returns table (
  id uuid,
  username text,
  blocked_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, b.created_at
    from blocks b
    join profiles p on p.id = b.blocked
   where b.blocker = auth.uid()
   order by b.created_at desc;
$$;

-- ───────────────────────────────── muting ────────────────────────────────────

-- Mute somebody. Nothing else changes: the friendship stands, the profile
-- stays visible, and they are not told — a block is the loud version of
-- this, and this is the one for somebody you are simply tired of racing.
create or replace function mute_lifter(their_id uuid)
returns text
language plpgsql
set search_path = public
as $$
begin
  if their_id = auth.uid() then
    return 'that is you';
  end if;

  insert into mutes (muter, muted)
  values (auth.uid(), their_id)
  on conflict (muter, muted) do nothing;

  return 'muted';
end;
$$;

create or replace function unmute_lifter(their_id uuid)
returns text
language plpgsql
set search_path = public
as $$
begin
  delete from mutes where muter = auth.uid() and muted = their_id;
  return 'unmuted';
end;
$$;

-- Who this account has muted, newest first. Only ever their own list.
create or replace function my_mutes()
returns table (
  id uuid,
  username text,
  muted_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, m.created_at
    from mutes m
    join profiles p on p.id = m.muted
   where m.muter = auth.uid()
   order by m.created_at desc;
$$;

-- ──────────────────────────────── the board ──────────────────────────────────

-- The board, best first, with everybody who asked to be left off it left off.
--
-- A function rather than a query from the phone, because "show me on
-- leaderboards" has to hold even when the client does not feel like adding
-- the filter. Placed accounts only: a tier on an account still in placements
-- is a column with something in it, not a rank it earned.
--
-- See the comment on my_friends() above — same reason, same fix.
-- [in_tier_idx]/[in_div_idx] narrow the board to one rung of the ladder — the
-- "ranked within your tier" list, where everybody on it is already level
-- with everybody else, and lp is what is left to tell them apart.
drop function if exists leaderboard(text, int);
-- And the one before xp was in what it returns.
drop function if exists leaderboard(text, int, int, int);
create or replace function leaderboard(
  in_country text default null,
  limit_to int default 100,
  in_tier_idx int default null,
  in_div_idx int default null
)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  wins int,
  losses int,
  avatar_url text,
  xp int
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, p.lp, p.wins, p.losses,
         p.avatar_url, p.xp
    from profiles p
   where p.placements_done >= 5
     and p.show_on_board
     -- Here this month: an account nobody has opened in thirty days does not
     -- hold a place on a board the people still playing are climbing. It
     -- keeps its rank, and is back on the board the day it opens the app.
     and p.last_seen > now() - interval '30 days'
     and (in_country is null
          or (p.country = in_country and p.show_country))
     and (in_tier_idx is null or p.tier_idx = in_tier_idx)
     and (in_div_idx is null or p.div_idx = in_div_idx)
   -- Level on rank and LP: more wins first, then fewer losses, then the name,
   -- so the order is the same every time the board is opened.
   order by p.tier_idx desc, p.div_idx desc, p.lp desc,
            p.wins desc, p.losses asc, p.username
   limit least(greatest(limit_to, 1), 500);
$$;

-- Where an account stands on that board, counting from 1, or null when it is
-- not on one. The same rules as above, so the number and the list can never
-- disagree about who is on it.
--
-- Takes whose place to compute rather than always asking about the caller,
-- so a profile card can show somebody else's position with the exact same
-- rules `my_board_place` uses for your own.
create or replace function board_place(for_id uuid, in_country text default null)
returns int
language sql
stable
security definer
set search_path = public
as $$
  select case
    when not exists (
      select 1 from profiles who
       where who.id = for_id
         and who.placements_done >= 5
         and who.show_on_board
         and who.last_seen > now() - interval '30 days'
         and (in_country is null
              or (who.country = in_country and who.show_country))
    ) then null
    else (
      select count(*)::int + 1
        from profiles p, profiles who
       where who.id = for_id
         and p.placements_done >= 5
         and p.show_on_board
         and p.last_seen > now() - interval '30 days'
         and (in_country is null
              or (p.country = in_country and p.show_country))
         -- leaderboard's order, one comparison at a time.
         and (p.tier_idx > who.tier_idx
           or (p.tier_idx = who.tier_idx and p.div_idx > who.div_idx)
           or (p.tier_idx = who.tier_idx and p.div_idx = who.div_idx
               and (p.lp > who.lp
                 or (p.lp = who.lp and p.wins > who.wins)
                 or (p.lp = who.lp and p.wins = who.wins
                     and p.losses < who.losses)
                 or (p.lp = who.lp and p.wins = who.wins
                     and p.losses = who.losses and p.username < who.username))))
    )
  end;
$$;

create or replace function my_board_place(in_country text default null)
returns int
language sql
stable
security definer
set search_path = public
as $$
  select board_place(auth.uid(), in_country);
$$;

-- ─────────────────────────────── a lifter's card ─────────────────────────────

-- Everything a profile card needs about somebody else, in one call rather
-- than the half-dozen a screen built from parts would need to make and then
-- hope agree with each other.
--
-- `security definer`, because the head-to-head reads both sides of a duel's
-- two sets — theirs as well as yours — and a set is normally readable only
-- by the lifter who did it. Every other function here works without that
-- because none of them needed to read a stranger's set; this is the first
-- that does.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists lifter_profile(uuid);
create or replace function lifter_profile(their_id uuid)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  total_reps int,
  best_set int,
  wins int,
  losses int,
  win_streak int,
  global_place int,
  country text,
  country_place int,
  is_friend bool,
  wins_vs_you int,
  losses_vs_you int,
  your_best_vs_them int,
  last_duel_at timestamptz,
  last_your_reps int,
  last_their_reps int,
  avatar_url text,
  title text,
  xp int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if their_id = me then
    raise exception 'use your own profile screen for that';
  end if;

  return query
  with h2h as (
    select
      d.created_at,
      case when d.challenger = me then cs.reps else ds.reps end as your_reps,
      case when d.challenger = me then ds.reps else cs.reps end as their_reps,
      (d.winner = me)::int      as you_won,
      (d.winner = their_id)::int as they_won
    from duels d
    join sets cs on cs.id = d.challenger_set
    join sets ds on ds.id = d.defender_set
    where (d.challenger = me and d.defender = their_id)
       or (d.challenger = their_id and d.defender = me)
  ),
  last as (
    select * from h2h order by created_at desc limit 1
  )
  select
    p.id, p.username, p.tier_idx, p.div_idx, p.lp, p.placements_done,
    p.total_reps, p.best_set, p.wins, p.losses, p.win_streak,
    -- Their country only if they chose to show it: the setting says "show
    -- my country", and a card that showed it anyway would make it a lie.
    board_place(p.id, null),
    case when p.show_country then p.country end,
    case when p.country is null or not p.show_country then null
         else board_place(p.id, p.country) end,
    exists (
      select 1 from friendships f
       where f.accepted_at is not null
         and ((f.requester = me and f.addressee = their_id)
           or (f.requester = their_id and f.addressee = me))
    ),
    -- wins_vs_you/losses_vs_you keep the same meaning as my_friends() above:
    -- wins_vs_you is theirs, losses_vs_you is yours. Swapping these would
    -- read as somebody's record flipped on every profile that opens on it.
    (select coalesce(sum(they_won), 0) from h2h)::int,
    (select coalesce(sum(you_won), 0) from h2h)::int,
    (select max(your_reps) from h2h),
    (select created_at from last),
    (select your_reps from last),
    (select their_reps from last),
    p.avatar_url,
    p.title,
    p.xp
  from profiles p
  where p.id = their_id;
end;
$$;

-- ───────────────────────────── the public card ───────────────────────────────

-- What a share card shows, for whoever a link reaches — the landing site's
-- /u/<username> page calls this signed out, which is the one place in the
-- app that has nobody signed in to check `to authenticated` against.
--
-- `security definer` for exactly that reason. Narrower than [lifter_profile]
-- on purpose: nothing about anybody else's relationship to this account, and
-- nothing that was not already true on the card the lifter chose to share.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists public_lifter_card(text);
create or replace function public_lifter_card(their_username text)
returns table (
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  wins int,
  losses int,
  best_set int,
  win_streak int,
  global_place int,
  country text,
  country_place int,
  avatar_url text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  who profiles;
begin
  select * into who from profiles where profiles.username = their_username;
  if who is null then
    return;
  end if;

  return query
  select
    who.username, who.tier_idx, who.div_idx, who.lp, who.wins, who.losses,
    who.best_set, who.win_streak,
    board_place(who.id, null),
    case when who.show_country then who.country end,
    case when who.country is null or not who.show_country then null
         else board_place(who.id, who.country) end,
    who.avatar_url;
end;
$$;

revoke all on function request_friend_with(uuid) from public;
grant execute on function request_friend_with(uuid) to authenticated;
revoke all on function request_friend(text) from public;
grant execute on function request_friend(text) to authenticated;
revoke all on function request_friend_by_code(text) from public;
grant execute on function request_friend_by_code(text) to authenticated;
revoke all on function answer_friend(uuid, boolean) from public;
grant execute on function answer_friend(uuid, boolean) to authenticated;
revoke all on function remove_friend(uuid) from public;
grant execute on function remove_friend(uuid) to authenticated;
revoke all on function my_friends() from public;
grant execute on function my_friends() to authenticated;
revoke all on function friend_requests() from public;
grant execute on function friend_requests() to authenticated;
revoke all on function find_lifters(text, int) from public;
grant execute on function find_lifters(text, int) to authenticated;
revoke all on function block_lifter(uuid) from public;
grant execute on function block_lifter(uuid) to authenticated;
revoke all on function unblock_lifter(uuid) from public;
grant execute on function unblock_lifter(uuid) to authenticated;
revoke all on function my_blocks() from public;
grant execute on function my_blocks() to authenticated;
revoke all on function leaderboard(text, int, int, int) from public;
grant execute on function leaderboard(text, int, int, int) to authenticated;
revoke all on function my_board_place(text) from public;
grant execute on function my_board_place(text) to authenticated;
revoke all on function board_place(uuid, text) from public;
grant execute on function board_place(uuid, text) to authenticated;
revoke all on function mute_lifter(uuid) from public;
grant execute on function mute_lifter(uuid) to authenticated;
revoke all on function unmute_lifter(uuid) from public;
grant execute on function unmute_lifter(uuid) to authenticated;
revoke all on function my_mutes() from public;
grant execute on function my_mutes() to authenticated;
revoke all on function lifter_profile(uuid) from public;
grant execute on function lifter_profile(uuid) to authenticated;
-- The one function in this file anon may call: it is what a share link is
-- for. Also granted to authenticated, since the app itself is signed in
-- when it renders your own card.
revoke all on function public_lifter_card(text) from public;
grant execute on function public_lifter_card(text) to anon, authenticated;

-- ========================================================================
-- duel.sql
-- ========================================================================

-- Finding an opponent, and settling with them.
--
-- The whole async duel is two calls: `find_opponent_set` hands you somebody
-- else's minute to race, and `settle_duel` compares yours against it and moves
-- both ranks. Nothing else writes to the ladder.
--
-- Both are `security definer`, which is what lets them write columns the
-- caller is forbidden to touch. That makes them the attack surface: every
-- argument is treated as hostile, and the caller's identity comes from
-- `auth.uid()` rather than from anything they passed in.

-- ─────────────────────────────── what was offered ───────────────────────────────

-- Which stored set was handed to whom, and how. settle_duel only settles a
-- set against the one it was raced against, and this is how it knows: the
-- pool's rules — near your level, never the same two twice, blocks, mutes,
-- who agreed to be challenged — are all decided in the two find_ functions,
-- and a set id the phone simply names went around every one of them. With
-- nothing but an id, a second account could store sets of nothing and be
-- beaten by the first over and over, for as much LP as anybody liked.
create table if not exists set_offers (
  set_id      uuid not null references sets on delete cascade,
  offered_to  uuid not null references profiles on delete cascade,
  offered_at  timestamptz not null default now(),
  -- Handed out by find_targeted_set: a rematch, which never moves a rank.
  targeted    boolean not null default false,
  primary key (set_id, offered_to)
);

alter table set_offers enable row level security;

-- The primary key leads with the set; deleting an account looks rows up by
-- whom they were offered to.
create index if not exists set_offers_offered_to_idx on set_offers (offered_to);

-- ───────────────────────────── finding somebody ──────────────────────────────

-- The open pool in the order find_opponent_set hands it out, oldest first:
-- exactly the sets it may offer, so it reads them in order and stops at the
-- first one that suits.
create index if not exists sets_pool_idx
  on sets (created_at)
  where claimed_by is null and challenge_target is null and live_match is null;

-- A stored set from somebody near your level that you have not faced.
--
-- Async on purpose: two people being free in the same minute is the hardest
-- thing to arrange in a fitness app, and it is not needed. You race their
-- minute, they find out they were raced.
-- Dropped first: the picture was added to what it returns.
drop function if exists find_opponent_set(int);
create or replace function find_opponent_set(within_levels int default 6)
returns table (
  set_id uuid,
  profile_id uuid,
  username text,
  tier_idx int,
  div_idx int,
  reps int,
  rep_times int[],
  avatar_url text,
  xp int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  me profiles;
  my_level int;
  kept_apart uuid[];
  found_set record;
begin
  -- Only a subscriber plays (see subscriptions.sql; off until switched on).
  perform require_pro();
  select * into me from profiles where id = auth.uid();
  if me is null then
    raise exception 'no profile for this account';
  end if;
  my_level := ladder_level(me.tier_idx, me.div_idx);

  -- Everybody this account may not be handed, gathered once from its own
  -- rows. Asked of each candidate in turn instead, as this used to be, it
  -- read every duel of every lifter near this level before choosing one:
  -- slower with each lifter who joined, and nearly a second at ten thousand.
  --   * Not somebody already faced. A ladder that keeps pairing the same two
  --     people is a ladder of two.
  --   * A block works whichever of the two is holding the phone, so both
  --     directions count. Neither is told which one it was.
  --   * A mute is one-directional and only ever counts from the muter's own
  --     side: it says "stop offering me them," not "stop offering them me."
  kept_apart := array(
    select d.defender from duels d where d.challenger = me.id
    union select d.challenger from duels d where d.defender = me.id
    union select b.blocked from blocks b where b.blocker = me.id
    union select b.blocker from blocks b where b.blocked = me.id
    union select m.muted from mutes m where m.muter = me.id
  );

  -- The pool oldest first (sets_pool_idx), stopping at the first set whose
  -- lifter passes, so the cost is the sets read before a match rather than
  -- everybody on the ladder.
  select s.id as set_id, p.id as profile_id, p.username, p.tier_idx,
         p.div_idx, s.reps, s.rep_times, p.avatar_url, p.xp
    into found_set
  from sets s
  join profiles p on p.id = s.profile_id
  where s.claimed_by is null
    and s.profile_id <> me.id
    -- Reserved for a rematch is not offered to the open pool — the whole
    -- point of naming a challenge_target is that only they can find it, with
    -- find_targeted_set below.
    and s.challenge_target is null
    -- Lifted live against somebody already (live.sql): it is settled against
    -- them, not left for the pool.
    and s.live_match is null
    -- Practice was lifted against nobody, and is not for racing.
    and not s.practice
    -- Near your level, measured in rungs rather than tiers: the difference
    -- between the top and the bottom of one tier is five divisions, and
    -- matching "same tier" would pair those two.
    and abs(ladder_level(p.tier_idx, p.div_idx) - my_level) <= within_levels
    and s.profile_id <> all (kept_apart)
    -- Whoever they said may challenge them. Enforced where the pairing is
    -- decided rather than on the phone, because a preference the client can
    -- skip is a preference in name only.
    and (
      p.challengeable = 'everyone'
      or (p.challengeable = 'friends' and exists (
            select 1 from friendships f
            where f.accepted_at is not null
              and ((f.requester = me.id and f.addressee = p.id)
                or (f.addressee = me.id and f.requester = p.id))
          ))
    )
  -- Oldest first: a set that has been waiting is the one most likely to have
  -- been forgotten about, and its owner is owed a result.
  order by s.created_at
  limit 1;

  if not found then
    return;
  end if;

  -- Written down, so settle_duel can tell this set was handed out here. The
  -- conflict is named by its constraint: `set_id` is also one of this
  -- function's output columns, and plpgsql reads a bare one as ambiguous.
  -- Offers a day old were never raced, and go.
  delete from set_offers o
   where o.offered_to = me.id and o.offered_at < now() - interval '1 day';
  insert into set_offers (set_id, offered_to, targeted)
  values (found_set.set_id, me.id, false)
  on conflict on constraint set_offers_pkey do update
    set offered_at = now(), targeted = false;

  return query select found_set.set_id, found_set.profile_id,
                      found_set.username, found_set.tier_idx,
                      found_set.div_idx, found_set.reps, found_set.rep_times,
                      found_set.avatar_url, found_set.xp;
end;
$$;

-- A specific lifter's reserved set, for a rematch.
--
-- The counterpart to `find_opponent_set` above: that one hands out anybody's
-- unraced minute at random, this one hands out exactly the one minute
-- [from_id] reserved for the caller by naming them in `challenge_target`.
-- Nothing about level or "not already faced" applies — a rematch is by
-- definition the same two people again, which is the one thing the open pool
-- refuses to pair.
drop function if exists find_targeted_set(uuid);
create or replace function find_targeted_set(from_id uuid)
returns table (
  set_id uuid,
  profile_id uuid,
  username text,
  tier_idx int,
  div_idx int,
  reps int,
  rep_times int[],
  avatar_url text,
  xp int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  found_set record;
begin
  -- Only a subscriber plays (see subscriptions.sql; off until switched on).
  perform require_pro();
  select s.id as set_id, p.id as profile_id, p.username, p.tier_idx,
         p.div_idx, s.reps, s.rep_times, p.avatar_url, p.xp
    into found_set
  from sets s
  join profiles p on p.id = s.profile_id
  where s.claimed_by is null
    and s.profile_id = from_id
    and s.challenge_target = auth.uid()
    and not s.practice
    -- A block still holds even over a challenge sent before it happened.
    and not exists (
      select 1 from blocks b
      where (b.blocker = auth.uid() and b.blocked = from_id)
         or (b.blocker = from_id and b.blocked = auth.uid())
    )
  order by s.created_at desc
  limit 1;

  if not found then
    return;
  end if;

  -- A rematch: settle_duel will settle it, and will not let it move a rank.
  insert into set_offers (set_id, offered_to, targeted)
  values (found_set.set_id, auth.uid(), true)
  on conflict on constraint set_offers_pkey do update
    set offered_at = now(), targeted = true;

  return query select found_set.set_id, found_set.profile_id,
                      found_set.username, found_set.tier_idx,
                      found_set.div_idx, found_set.reps, found_set.rep_times,
                      found_set.avatar_url, found_set.xp;
end;
$$;

-- ─────────────────────────────── placements ─────────────────────────────────

-- Where an account stands after its placement duel.
--
-- One ranked duel places an account, and placement_rank puts everybody at
-- Iron V whatever the result. `done` is how many have been played counting
-- this one, so it is always at least one here; the guard is for a caller
-- that asks before any.
-- The parameters are named `from_*` because the returned columns are called
-- `tier_idx`, `div_idx` and `lp`, and Postgres refuses a function whose
-- inputs and outputs share a name.
create or replace function place_after(
  done int, wins int, from_tier int, from_div int, from_lp int
)
returns table (tier_idx int, div_idx int, lp int)
language plpgsql
immutable
set search_path = public
as $$
begin
  if done < 1 then
    return query select from_tier, from_div, from_lp;
  else
    return query select * from placement_rank(wins);
  end if;
end;
$$;

-- Accounts caught part-way through the old five placements when one became
-- enough: they have played their placement, so they are placed — Iron V, no
-- LP, and marked done the way every placed account is.
do $$
begin
  perform set_config('outrepd.settling', 'on', true);
  update profiles
     set placements_done = 5, tier_idx = 0, div_idx = 0, lp = 0
   where placements_done between 1 and 4;
  perform set_config('outrepd.settling', 'off', true);
end $$;

-- ───────────────────────────── settling a duel ───────────────────────────────

-- Compares the caller's set against a stored one and moves both ranks.
--
-- The caller passes only their own set and the one they faced. Everything that
-- decides the outcome — the reps, who gave up, both tiers — is read from the
-- rows, never from arguments, because an argument is whatever the phone felt
-- like sending.
--
-- Dropped first: a function's result columns cannot change in place, and
-- `was_ranked` was added after the others.
drop function if exists settle_duel(uuid, uuid, boolean);
-- The two-argument one from before `ranked` existed. A new argument makes a
-- second function beside the old rather than replacing it, and the old one
-- stayed on the live database, callable, without the checks added since —
-- found on 2026-10-15 by comparing the live schema with this file. No app
-- that shipped calls it: every one sends `ranked`.
drop function if exists settle_duel(uuid, uuid);
create or replace function settle_duel(
  my_set uuid,
  their_set uuid,
  ranked boolean default true
)
returns table (
  duel_id uuid,
  won boolean,
  lp_delta int,
  tier_idx int,
  div_idx int,
  lp int,
  -- The record and the placements, read back off the row this same call just
  -- wrote. The app used to be trusted to derive these locally from the same
  -- rules — win/loss, the streak, the five placement duels — and two copies
  -- of a rule is two rules. Returning them is cheaper than that ever going
  -- wrong.
  wins int,
  losses int,
  win_streak int,
  best_streak int,
  placements_done int,
  placement_wins int,
  -- Whether it moved the ladder after all. The phone asks for ranked; the
  -- rules above can still make it friendly — a rematch, a third duel in a
  -- day with the same lifter — and the result screen has to say which.
  was_ranked boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  mine sets;
  theirs sets;
  me profiles;
  them profiles;
  me_after profiles;
  i_won boolean;
  after record;
  their_after record;
  d_id uuid;
  is_ranked boolean := coalesce(ranked, true);
  my_placing boolean;
  their_placing boolean;
  my_delta int;
  their_delta int;
  offer set_offers;
begin
  -- Only a subscriber plays (see subscriptions.sql; off until switched on).
  perform require_pro();
  select * into mine   from sets where id = my_set    for update;
  select * into theirs from sets where id = their_set for update;

  if mine is null or theirs is null then
    raise exception 'set not found';
  end if;
  if mine.profile_id <> auth.uid() then
    raise exception 'that is not your set';
  end if;
  if mine.claimed_by is not null or theirs.claimed_by is not null then
    -- A set is faced once. Without this, replaying the same pair of ids is
    -- free LP for whoever calls it twice.
    raise exception 'one of these sets has already been played';
  end if;
  if mine.profile_id = theirs.profile_id then
    raise exception 'cannot duel yourself';
  end if;
  if mine.practice or theirs.practice then
    raise exception 'a practice set is not raced';
  end if;

  -- How the two sets met decides whether they may be settled at all, and
  -- whether the result moves a rank. Not the `ranked` the phone sends: that
  -- is only ever allowed to make a duel *less* than what it was.
  if mine.live_match is not null or theirs.live_match is not null then
    -- Lifted against each other on camera. Only live.sql writes live_match,
    -- and it writes the same one into both sets of a match.
    if mine.live_match is distinct from theirs.live_match then
      raise exception 'these sets were not raced against each other';
    end if;
    select lm.ranked into is_ranked
      from live_matches lm where lm.id = mine.live_match;
    is_ranked := coalesce(is_ranked, false);
  else
    -- Raced from the pool or from a challenge: their set has to be one the
    -- find_ functions handed this account, recently, and this account's set
    -- the one lifted after it.
    select * into offer from set_offers o
     where o.set_id = theirs.id
       and o.offered_to = auth.uid()
       and o.offered_at > now() - interval '2 hours';
    if not found then
      raise exception 'that set was never handed to you';
    end if;
    if mine.created_at < offer.offered_at then
      raise exception 'your set has to be the one lifted against theirs';
    end if;
    -- A rematch never moves a rank: two people who can arrange rematches
    -- between themselves could otherwise arrange each other's LP.
    if offer.targeted then
      is_ranked := false;
    end if;
  end if;

  -- No cap on how often the same two can pay each other. There were two a
  -- day; but two people the search pairs are a match like any other, and a
  -- friend's match is friendly from the start, so every ranked one counts.

  select * into me   from profiles where id = mine.profile_id   for update;
  select * into them from profiles where id = theirs.profile_id for update;

  -- Walking out is a loss whatever the count said at the moment you left.
  i_won := case
             when mine.gave_up   then false
             when theirs.gave_up then true
             else mine.reps >= theirs.reps
           end;

  -- The guard on profiles lets these two updates through, and only these.
  perform set_config('outrepd.settling', 'on', true);

  -- An account's first ranked duel places it: no LP is paid on it, and
  -- whatever the result it starts at Iron V (place_after). A placed account
  -- is marked with placements_done = 5, not 1 — five is what every check on
  -- the server reads as placed, and what an app from before one duel was
  -- enough reads that way too.
  my_placing    := is_ranked and me.placements_done   < 5;
  their_placing := is_ranked and them.placements_done < 5;

  if not is_ranked then
    -- A friend room is a real duel and not a rung. It moves nothing: not the
    -- ladder, not the placements, not the win record the ladder is built on.
    my_delta := 0;
    their_delta := 0;
    select me.tier_idx, me.div_idx, me.lp into after;
    select them.tier_idx, them.div_idx, them.lp into their_after;
  elsif my_placing then
    my_delta := 0;
    select * into after from place_after(
      me.placements_done + 1,
      me.placement_wins + (case when i_won then 1 else 0 end),
      me.tier_idx, me.div_idx, me.lp
    );
  else
    -- Weighed by the two ranks as they stood when the duel was played.
    my_delta := lp_for(i_won, mine.reps, theirs.reps,
                       ladder_level(me.tier_idx, me.div_idx),
                       ladder_level(them.tier_idx, them.div_idx));
    select * into after from apply_lp(
      me.tier_idx, me.div_idx, me.lp, my_delta, me.peak_tier_idx
    );
  end if;

  if is_ranked and their_placing then
    their_delta := 0;
    select * into their_after from place_after(
      them.placements_done + 1,
      them.placement_wins + (case when i_won then 0 else 1 end),
      them.tier_idx, them.div_idx, them.lp
    );
  elsif is_ranked then
    their_delta := lp_for(not i_won, theirs.reps, mine.reps,
                          ladder_level(them.tier_idx, them.div_idx),
                          ladder_level(me.tier_idx, me.div_idx));
    select * into their_after from apply_lp(
      them.tier_idx, them.div_idx, them.lp, their_delta, them.peak_tier_idx
    );
  end if;

  -- Everything below writes the ladder, and an unranked duel writes none of
  -- it. It is recorded in `duels` and that is all.
  if is_ranked then

    -- Every bare column read below is qualified as `profiles.col` rather than
    -- `col`. RETURNS TABLE above declares output columns of these same names
    -- (wins, losses, win_streak, best_streak, placements_done,
    -- placement_wins), which plpgsql turns into variables of those exact
    -- names in scope for the rest of the function — so an unqualified read
    -- here is genuinely ambiguous between "the column this statement is
    -- updating" and "the output this function will return". The assignment
    -- targets (the name left of each `=`) never need this: SET's target list
    -- can only ever mean the column.
    update profiles set
      tier_idx = after.tier_idx,
      div_idx  = after.div_idx,
      lp       = after.lp,
      peak_tier_idx = greatest(peak_tier_idx, after.tier_idx),
      -- Every ranked duel leaves an account placed: it was already, or this
      -- was its placement.
      placements_done = 5,
      placement_wins  = profiles.placement_wins
                        + (case when my_placing and i_won then 1 else 0 end),
      -- A placement is a real duel and its result is a real result, so the
      -- record counts it even though it pays no LP.
      wins        = profiles.wins   + (case when i_won then 1 else 0 end),
      losses      = profiles.losses + (case when i_won then 0 else 1 end),
      win_streak  = case when i_won then profiles.win_streak + 1 else 0 end,
      best_streak = greatest(profiles.best_streak,
                             case when i_won then profiles.win_streak + 1 else 0 end),
      -- Reps were counted when the set was stored, by the trigger on `sets`.
      updated_at = now()
    where id = me.id;

    update profiles set
      tier_idx = their_after.tier_idx,
      div_idx  = their_after.div_idx,
      lp       = their_after.lp,
      peak_tier_idx = greatest(peak_tier_idx, their_after.tier_idx),
      placements_done = 5,
      placement_wins  = profiles.placement_wins
                        + (case when their_placing and not i_won then 1 else 0 end),
      wins        = profiles.wins   + (case when i_won then 0 else 1 end),
      losses      = profiles.losses + (case when i_won then 1 else 0 end),
      win_streak  = case when i_won then 0 else profiles.win_streak + 1 end,
      best_streak = greatest(profiles.best_streak,
                             case when i_won then 0 else profiles.win_streak + 1 end)
      -- Their reps were counted when their set was stored, not again here.
    where id = them.id;
  end if;

  insert into duels (
    challenger, defender, challenger_set, defender_set,
    winner, ranked, lp_challenger, lp_defender
  ) values (
    me.id, them.id, mine.id, theirs.id,
    case when i_won then me.id else them.id end,
    is_ranked, my_delta, their_delta
  ) returning id into d_id;

  update sets set claimed_by = d_id where id in (mine.id, theirs.id);
  delete from set_offers o where o.set_id in (mine.id, theirs.id);

  perform set_config('outrepd.settling', 'off', true);

  -- Read back rather than tracked through the branches above: the update
  -- above may not even have run (a friend duel touches nothing), and this is
  -- correct either way — the row's current state, whatever wrote it last.
  select * into me_after from profiles where id = me.id;

  return query select d_id, i_won, my_delta,
                      after.tier_idx, after.div_idx, after.lp,
                      me_after.wins, me_after.losses, me_after.win_streak,
                      me_after.best_streak, me_after.placements_done,
                      me_after.placement_wins, is_ranked;
end;
$$;

-- ──────────────────────────────── the history ────────────────────────────────

-- The caller's duels, newest first, from the caller's side: what the phone's
-- history is made of. The phone writes down what it watches happen, but not
-- everything does: a set raced while its owner was away happens on the other
-- phone, a live result can land after its screen was closed, and a result
-- can be settled here and its answer lost on the way back. Each of those
-- moved the rank and reached nobody's history. Fifty, the length of the
-- history the phone keeps.
--
-- `raced_while_away` marks the first kind: the only duels a phone that kept
-- its own history before this existed never wrote down.
drop function if exists my_raced_sets();
create or replace function my_duels()
returns table (
  duel_id uuid,
  played_at timestamptz,
  opponent_name text,
  opponent_tier int,
  you_won boolean,
  your_reps int,
  their_reps int,
  lp_delta int,
  raced_while_away boolean
)
language sql
stable
security definer
set search_path = public
as $$
  -- Each side read from its own index and cut at fifty before the two are
  -- put together, so a lifter with thousands of duels costs a hundred rows.
  with mine as (
    (select d.* from duels d where d.challenger = auth.uid()
      order by d.created_at desc limit 50)
    union all
    (select d.* from duels d where d.defender = auth.uid()
      order by d.created_at desc limit 50)
  )
  select d.id, d.created_at, p.username, p.tier_idx,
         coalesce(d.winner = auth.uid(), false),
         case when d.challenger = auth.uid() then cs.reps else ds.reps end,
         case when d.challenger = auth.uid() then ds.reps else cs.reps end,
         case when d.challenger = auth.uid() then d.lp_challenger
              else d.lp_defender end,
         d.defender = auth.uid() and ds.live_match is null
    from mine d
    join sets cs on cs.id = d.challenger_set
    join sets ds on ds.id = d.defender_set
    join profiles p on p.id = case when d.challenger = auth.uid()
                                   then d.defender else d.challenger end
   order by d.created_at desc
   limit 50;
$$;

revoke all on function my_duels() from public, anon;
grant execute on function my_duels() to authenticated;

revoke all on function settle_duel(uuid, uuid, boolean) from public;
grant execute on function settle_duel(uuid, uuid, boolean) to authenticated;
revoke all on function find_opponent_set(int) from public;
grant execute on function find_opponent_set(int) to authenticated;
revoke all on function find_targeted_set(uuid) from public;
grant execute on function find_targeted_set(uuid) to authenticated;

-- ========================================================================
-- notify.sql
-- ========================================================================

-- OUTREPD — telling people what happened while they were away.
--
-- This is the half of the async duel that was missing. You race somebody's
-- stored minute and see the result immediately; *they* were not there. Until
-- this file, nothing ever told them — their set was raced, their rank moved,
-- their record changed, and the app said nothing the next time they opened
-- it. A ladder people cannot feel themselves moving on is a ladder nobody
-- plays twice.
--
-- Written by triggers rather than by the app, for the same reason the ladder
-- is: the person being told is not the person holding the phone. A client
-- cannot be asked to notify somebody else, because a client that can write
-- into somebody else's notifications can write anything it likes there.
--
-- Nothing here notifies you about your own actions. You were present for
-- those, and the screen already said so.

create table if not exists notifications (
  id          uuid primary key default gen_random_uuid(),

  -- Who it is for.
  profile_id  uuid not null references profiles on delete cascade,
  created_at  timestamptz not null default now(),
  read_at     timestamptz,

  kind text not null
       check (kind in ('raced', 'friend_request', 'friend_accepted', 'challenged', 'live_invite')),

  -- Who caused it. The id can go — accounts get deleted — so the name is
  -- kept beside it: a notification that has forgotten who it was about is
  -- worse than no notification.
  actor       uuid references profiles on delete set null,
  actor_name  text not null default '',

  -- Only for 'raced'. The counts are stored rather than looked up, because
  -- the sets they came from are the other half of a duel that is over, and
  -- this row has to still make sense in a year.
  duel_id     uuid references duels on delete cascade,
  you_won     bool,
  your_reps   int,
  their_reps  int
);

-- Only for 'raced': what the duel did to the raced lifter's LP, so the card
-- they share from the notification can say it. Null for an unranked duel,
-- which moves nothing. Added after the table, so an existing one gains it.
alter table notifications add column if not exists lp_delta int;

-- For a project that already has the table from before 'challenged' and
-- 'live_invite' (live.sql) existed.
alter table notifications drop constraint if exists notifications_kind_check;
alter table notifications add constraint notifications_kind_check
  check (kind in ('raced', 'friend_request', 'friend_accepted', 'challenged', 'live_invite'));

-- Everything reads "mine, newest first", and the badge counts the unread.
create index if not exists notifications_for_profile_idx
  on notifications (profile_id, created_at desc);
create index if not exists notifications_unread_idx
  on notifications (profile_id) where read_at is null;
-- The foreign keys' own indexes, for deleting an account or a duel; see
-- sets_challenge_target_idx in schema.sql.
create index if not exists notifications_actor_idx
  on notifications (actor) where actor is not null;
create index if not exists notifications_duel_idx
  on notifications (duel_id) where duel_id is not null;

alter table notifications enable row level security;

-- Yours and nobody else's. There is deliberately no insert policy: every row
-- here is written by a trigger below, and a client that could insert one
-- could tell somebody they had been beaten by anyone it liked.
drop policy if exists "a lifter reads their own notifications" on notifications;
create policy "a lifter reads their own notifications"
  on notifications for select
  to authenticated
  using ((select auth.uid()) = profile_id);

drop policy if exists "a lifter clears their own notifications" on notifications;
create policy "a lifter clears their own notifications"
  on notifications for delete
  to authenticated
  using ((select auth.uid()) = profile_id);

-- ──────────────────────────── being raced ────────────────────────────────────

-- The defender finds out.
--
-- `settle_duel` inserts the duel, so this fires inside it. The challenger is
-- not told: they are the one who just watched it happen.
create or replace function notify_defender()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  challenger_name text;
  mine int;
  theirs int;
begin
  if not exists (
    select 1 from profiles
     where id = new.defender and notify_raced
  ) then
    return new;
  end if;

  select username into challenger_name from profiles where id = new.challenger;
  select reps into theirs from sets where id = new.challenger_set;
  select reps into mine   from sets where id = new.defender_set;

  insert into notifications (
    profile_id, kind, actor, actor_name,
    duel_id, you_won, your_reps, their_reps, lp_delta
  ) values (
    new.defender, 'raced', new.challenger, coalesce(challenger_name, ''),
    new.id, new.winner = new.defender, mine, theirs,
    case when new.ranked then new.lp_defender end
  );

  return new;
end;
$$;

drop trigger if exists duels_notify_defender on duels;
create trigger duels_notify_defender
  after insert on duels
  for each row execute function notify_defender();

-- ─────────────────────────── friend requests ─────────────────────────────────

-- Somebody asked. A request nobody is told about is a request that sits
-- unanswered forever, which is how the friends screen ends up looking broken.
create or replace function notify_friend_request()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  asker text;
begin
  -- Only a real invitation. A row that arrives already accepted came from
  -- somebody asking back, and that case is handled below.
  if new.accepted_at is not null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.addressee and notify_friend_request
  ) then
    return new;
  end if;

  select username into asker from profiles where id = new.requester;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.addressee, 'friend_request', new.requester, coalesce(asker, ''));
  return new;
end;
$$;

drop trigger if exists friendships_notify_request on friendships;
create trigger friendships_notify_request
  after insert on friendships
  for each row execute function notify_friend_request();

-- And they said yes.
create or replace function notify_friend_accepted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  accepter text;
begin
  -- Only on the moment it is accepted, not on every later write to the row.
  if old.accepted_at is not null or new.accepted_at is null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.requester and notify_friend_ok
  ) then
    return new;
  end if;

  select username into accepter from profiles where id = new.addressee;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.requester, 'friend_accepted', new.addressee,
          coalesce(accepter, ''));
  return new;
end;
$$;

drop trigger if exists friendships_notify_accepted on friendships;
create trigger friendships_notify_accepted
  after update on friendships
  for each row execute function notify_friend_accepted();

-- ────────────────────────────── being challenged ──────────────────────────────

-- Somebody reserved a set naming this account — a rematch. Fires from `sets`
-- rather than `duels`: a challenge is not a duel yet, it is one set waiting
-- for the other half, which is exactly the moment the target has to be told.
create or replace function notify_challenged()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  challenger_name text;
begin
  if new.challenge_target is null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.challenge_target and notify_challenged
  ) then
    return new;
  end if;

  -- Blocked either way round: the set is stored, find_targeted_set will
  -- never hand it over, and nobody is told — the one who sent it least of
  -- all, since a block is not announced.
  if exists (
    select 1 from blocks b
     where (b.blocker = new.challenge_target and b.blocked = new.profile_id)
        or (b.blocker = new.profile_id and b.blocked = new.challenge_target)
  ) then
    return new;
  end if;

  select username into challenger_name from profiles where id = new.profile_id;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.challenge_target, 'challenged', new.profile_id,
          coalesce(challenger_name, ''));
  return new;
end;
$$;

drop trigger if exists sets_notify_challenged on sets;
create trigger sets_notify_challenged
  after insert on sets
  for each row execute function notify_challenged();

-- ──────────────────────────────── reading ────────────────────────────────────

-- Mine, newest first.
--
-- Dropped first: Postgres refuses `create or replace` when a table-returning
-- function's column set changes shape (adding `actor` and `lp_delta` did),
-- and fails with a "cannot change return type" error that names DROP as the
-- fix.
drop function if exists my_notifications(int);
create or replace function my_notifications(limit_to int default 50)
returns table (
  id uuid,
  kind text,
  created_at timestamptz,
  unread boolean,
  actor uuid,
  actor_name text,
  you_won boolean,
  your_reps int,
  their_reps int,
  lp_delta int
)
language sql
stable
set search_path = public
as $$
  select n.id, n.kind, n.created_at, n.read_at is null,
         n.actor, n.actor_name, n.you_won, n.your_reps, n.their_reps,
         n.lp_delta
    from notifications n
   where n.profile_id = auth.uid()
   order by n.created_at desc
   limit least(greatest(limit_to, 1), 200);
$$;

-- What the dot on the bell is counting.
create or replace function unread_notifications()
returns int
language sql
stable
set search_path = public
as $$
  select count(*)::int from notifications
   where profile_id = auth.uid() and read_at is null;
$$;

-- Marks the lot as read, which is what opening the screen means.
--
-- A function rather than an update policy: the only thing anybody may change
-- about a notification is whether they have seen it, and a policy broad
-- enough to allow that is broad enough to let somebody rewrite what it says.
create or replace function read_notifications()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  touched int;
begin
  update notifications set read_at = now()
   where profile_id = auth.uid() and read_at is null;
  get diagnostics touched = row_count;
  return touched;
end;
$$;

revoke all on function my_notifications(int) from public;
grant execute on function my_notifications(int) to authenticated;
revoke all on function unread_notifications() from public;
grant execute on function unread_notifications() to authenticated;
revoke all on function read_notifications() from public;
grant execute on function read_notifications() to authenticated;

-- ========================================================================
-- push.sql
-- ========================================================================

-- OUTREPD — push notifications.
--
-- notify.sql writes a notice when somebody races your set, asks to be your
-- friend, accepts, or wants a rematch. Until this file you only saw it the
-- next time you happened to open the app. Now each new notice is also sent
-- to the phones signed in to the account, through Firebase.
--
-- Three pieces:
--   push_tokens          each phone's Firebase address, and the language the
--                        app on it is in, so a push reads like the app does.
--   register/forget      the only way a phone writes that table: as the
--                        signed-in account, and only its own rows.
--   a trigger            on every new notice, calls the `push` edge function
--                        with the notice's id and nothing else.
--
-- Nothing here holds a secret. The function looks the notice up itself with
-- the service key Supabase gives every edge function, and marks it pushed as
-- it sends, so a call can only ever push a notice once — whoever makes it.
-- See supabase/functions/push/index.ts for deploying it.

create table if not exists push_tokens (
  token       text primary key,
  profile_id  uuid not null references profiles on delete cascade,
  platform    text not null default 'android'
              check (platform in ('android', 'ios')),
  -- A language the app ships in; the function falls back to English.
  language    text not null default 'en',
  updated_at  timestamptz not null default now()
);

create index if not exists push_tokens_profile_idx on push_tokens (profile_id);

-- No policies: nobody reads or writes it directly. The functions below are
-- the whole of the phone's access, and the edge function uses the service key.
alter table push_tokens enable row level security;

-- When a notice went out. Set by the edge function as it sends, and the
-- reason a second call for the same notice sends nothing.
alter table notifications add column if not exists pushed_at timestamptz;

-- This phone is where the signed-in account's pushes go. A token already on
-- another account moves: a phone gets one address, and whoever signed in on
-- it last is who it belongs to.
create or replace function register_push_token(
  push_token text,
  push_platform text default 'android',
  push_language text default 'en'
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  if push_token is null or length(push_token) < 20 or length(push_token) > 4096 then
    raise exception 'not a push token';
  end if;

  insert into push_tokens (token, profile_id, platform, language, updated_at)
  values (
    push_token,
    auth.uid(),
    case when push_platform = 'ios' then 'ios' else 'android' end,
    coalesce(nullif(left(push_language, 8), ''), 'en'),
    now()
  )
  on conflict (token) do update
    set profile_id = excluded.profile_id,
        platform   = excluded.platform,
        language   = excluded.language,
        updated_at = excluded.updated_at;
end;
$$;

revoke all on function register_push_token(text, text, text) from public, anon;
grant execute on function register_push_token(text, text, text) to authenticated;

-- Before signing out: this phone stops getting the account's pushes. Only
-- the account's own row; somebody else's token is not this account's to drop.
create or replace function forget_push_token(push_token text)
returns void
language sql
security definer
set search_path = public
as $$
  delete from push_tokens
   where token = push_token
     and profile_id = auth.uid();
$$;

revoke all on function forget_push_token(text) from public, anon;
grant execute on function forget_push_token(text) to authenticated;

-- Every new notice is handed to the `push` edge function. pg_net queues the
-- call and returns at once, so storing the notice never waits on Firebase;
-- and any failure here is swallowed, because a push that cannot be sent must
-- never be the reason a notice is not stored.
--
-- In `extensions`, not `public`: an extension's objects in the API's own
-- schema sit beside the app's functions, and Supabase's advisor flags it.
-- pg_net cannot be moved in place, so one an earlier installer put in
-- public is dropped and made again. Nothing here names it by that schema —
-- the trigger calls net.http_post, and `net` stays where it is. Left alone,
-- with a notice, if something else in the project has come to depend on it.
do $$
begin
  if exists (select 1 from pg_extension
              where extname = 'pg_net'
                and extnamespace = 'public'::regnamespace) then
    begin
      drop extension pg_net;
    exception when dependent_objects_still_exist then
      raise notice 'pg_net stays in public: %', sqlerrm;
    end;
  end if;
end;
$$;
create extension if not exists pg_net with schema extensions;

create or replace function send_push()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    perform net.http_post(
      url := 'https://pzhdakzjbjyxhspymjhb.supabase.co/functions/v1/push',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object('id', new.id)
    );
  exception when others then
    raise warning 'push not queued: %', sqlerrm;
  end;
  return new;
end;
$$;

revoke all on function send_push() from public, anon, authenticated;

drop trigger if exists send_push on notifications;
create trigger send_push
  after insert on notifications
  for each row execute function send_push();

-- ──────────────────────────────── report alerts ──────────────────────────────

-- Every new report is handed to the `report-alert` edge function, which
-- emails whoever answers reports — the terms promise action within 24 hours,
-- and nothing in the app shows the reports table to anybody.
--
-- The same shape as send_push above: only the report's id goes out, and the
-- function looks the report up itself and claims it by setting alerted_at,
-- so any number of calls for one report email once and a caller who is not
-- this trigger can do nothing but that. No secret, which is what let this
-- move out of the SQL editor and into install.sql. It replaces a trigger
-- named "report-alert", made by hand with a secret written into it.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
     where table_schema = 'public'
       and table_name = 'reports'
       and column_name = 'alerted_at'
  ) then
    alter table reports add column alerted_at timestamptz;
    -- Every report already filed was emailed about by the trigger this
    -- replaces. Only the first time, when the column is new.
    update reports set alerted_at = created_at;
  end if;
end;
$$;

create or replace function send_report_alert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    perform net.http_post(
      url := 'https://pzhdakzjbjyxhspymjhb.supabase.co/functions/v1/report-alert',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object('report_id', new.id)
    );
  exception when others then
    -- A report is stored whether or not the alert goes.
    raise warning 'report alert not queued: %', sqlerrm;
  end;
  return new;
end;
$$;

revoke all on function send_report_alert() from public, anon, authenticated;

drop trigger if exists "report-alert" on reports;
drop trigger if exists send_report_alert on reports;
create trigger send_report_alert
  after insert on reports
  for each row execute function send_report_alert();

-- ========================================================================
-- live.sql
-- ========================================================================

-- OUTREPD — live matches: both lifters on camera at the same time.
--
-- Two ways in:
--   ranked   `find_live_opponent` is called every second or so while the
--            search screen counts to fifteen. It pairs the caller with
--            whoever has been waiting longest near their level, or puts the
--            caller in the queue to be found. After fifteen seconds with
--            nobody, the app leaves the queue and races a saved set instead
--            (duel.sql) — the ranked button always ends in a match.
--   friend   `invite_live` asks one friend, who gets a notice and a push and
--            has a minute to join. Friendly: it moves no rank.
--
-- Then both phones say they are on the match screen (`live_ready`) — in
-- position or not — and the server picks one instant for the round to start,
-- ten seconds after the second of them, handed to each phone as "this many
-- milliseconds from now" so neither phone's clock has to be right.
--
-- The counts travel phone to phone over Supabase Realtime while the round
-- runs; that is only for showing them. What settles the match is the two
-- sets, sent at the end (`finish_live_match`) and judged by `settle_duel` —
-- the same rule as every other duel, not a second copy of it. Each phone also
-- reports its count every few seconds (`report_live_count`), so a phone that
-- drops out mid-round still has a number: the round finishes on the clock,
-- and the one that vanished is judged on the last count that arrived.

create table if not exists live_matches (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  ranked      boolean not null,

  -- For an invite, `a` asked and `b` was asked. For ranked, `a` made the
  -- pairing and `b` was the one waiting in the queue.
  a           uuid not null references profiles on delete cascade,
  b           uuid not null references profiles on delete cascade,

  status      text not null default 'invited'
              check (status in ('invited', 'ready', 'live', 'done',
                                'cancelled', 'declined', 'expired')),

  -- The invite's minute.
  expires_at  timestamptz,
  -- How long the two have to both reach the match screen once paired.
  ready_by    timestamptz,

  a_ready     boolean not null default false,
  b_ready     boolean not null default false,

  -- The one instant the round starts on both phones.
  starts_at   timestamptz,

  -- The last count each phone reported, and when.
  a_reps      int not null default 0,
  b_reps      int not null default 0,
  a_seen      timestamptz,
  b_seen      timestamptz,

  a_set       uuid references sets on delete set null,
  b_set       uuid references sets on delete set null,
  duel        uuid references duels on delete set null
);

create index if not exists live_matches_b_idx on live_matches (b, status);
create index if not exists live_matches_a_idx on live_matches (a, status);
-- The foreign keys' own indexes; see sets_challenge_target_idx in schema.sql.
create index if not exists live_matches_a_set_idx
  on live_matches (a_set) where a_set is not null;
create index if not exists live_matches_b_set_idx
  on live_matches (b_set) where b_set is not null;
create index if not exists live_matches_duel_idx
  on live_matches (duel) where duel is not null;

-- The match a rematch was asked for after; null for every other match.
alter table live_matches
  add column if not exists rematch_of uuid references live_matches on delete set null;
create index if not exists live_matches_rematch_of_idx
  on live_matches (rematch_of) where rematch_of is not null;

-- After the round, on the result screen: when each phone last said it was
-- still there, and when it left. What the other phone's rematch button reads
-- (live_result_presence).
alter table live_matches add column if not exists a_result_seen timestamptz;
alter table live_matches add column if not exists b_result_seen timestamptz;
alter table live_matches add column if not exists a_left_result timestamptz;
alter table live_matches add column if not exists b_left_result timestamptz;

-- Nobody reads or writes it directly; the functions below are the only way.
alter table live_matches enable row level security;

-- Who is searching for a ranked live match right now.
create table if not exists live_queue (
  profile_id  uuid primary key references profiles on delete cascade,
  level       int not null,
  joined_at   timestamptz not null default now(),
  -- Refreshed by every call from the search screen. Somebody whose phone
  -- stopped asking a few seconds ago has left, whatever the row says.
  seen_at     timestamptz not null default now()
);

alter table live_queue enable row level security;

-- ─────────────────────────────── ranked: the queue ─────────────────────────────

-- How far apart in level two lifters may be, given how long one of them has
-- searched: close at first, wider every five seconds, and the whole ladder's
-- worth of reach before the fifteen seconds after which the app gives up and
-- races a recorded set instead. A level is one division; a tier is five.
create or replace function live_reach(waited_seconds double precision)
returns int
language sql
immutable
set search_path = public
as $$
  select case
           when waited_seconds < 5 then 2
           when waited_seconds < 10 then 6
           else 12
         end
$$;

-- For the search screen while it waits: how many are searching right now,
-- and how many have had the app open in the last few minutes. Counts only;
-- nobody in them is named.
create or replace function live_online()
returns table (searching int, online int)
language sql
stable
security definer
set search_path = public
as $$
  select
    (select count(*)::int from live_queue q
      where q.seen_at > now() - interval '5 seconds'
        and q.profile_id <> auth.uid()),
    (select count(*)::int from profiles p
      where p.last_seen > now() - interval '3 minutes'
        and p.id <> auth.uid());
$$;

revoke all on function live_reach(double precision) from public, anon;
revoke all on function live_online() from public, anon;
grant execute on function live_online() to authenticated;

-- Pairs the caller with somebody live, or waits in the queue. Returns one row
-- once there is somebody to race, and nothing while there is not.
-- Dropped first: the opponent's picture was added to what it returns, and a
-- function's columns cannot change in place.
drop function if exists find_live_opponent();
create or replace function find_live_opponent()
returns table (
  match_id uuid,
  opponent_id uuid,
  opponent_name text,
  opponent_tier int,
  opponent_div int,
  opponent_avatar text,
  opponent_xp int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  me profiles;
  my_level int;
  my_wait double precision;
  paired live_matches;
  waiting live_queue;
begin
  perform require_pro();
  select * into me from profiles where id = auth.uid();
  if me is null then
    raise exception 'no profile for this account';
  end if;
  my_level := ladder_level(me.tier_idx, me.div_idx);
  -- How long this search has run: the phone asks again every few seconds,
  -- and the queue row keeps when it first joined.
  my_wait := coalesce(
    extract(epoch from now() - (select q.joined_at from live_queue q
                                 where q.profile_id = me.id)),
    0);

  -- One pairing at a time, so two people can never both take the same third.
  perform pg_advisory_xact_lock(hashtext('outrepd.live_queue'));

  -- Whoever stopped asking a minute ago has gone: the app was closed mid
  -- search, or the phone lost its connection, and leave_live_queue never
  -- came. Left there, the queue grows with everybody who ever did that, and
  -- every search reads all of them; and coming back to search later would
  -- start from the old row's joined_at, as if they had waited all along.
  delete from live_queue q where q.seen_at < now() - interval '1 minute';

  -- Somebody else's call may already have paired this account.
  select * into paired from live_matches lm
   where lm.b = me.id and lm.ranked and lm.status = 'ready'
     and lm.created_at > now() - interval '30 seconds'
   order by lm.created_at desc
   limit 1;
  if paired.id is not null then
    delete from live_queue where live_queue.profile_id = me.id;
    return query
      select paired.id, p.id, p.username, p.tier_idx, p.div_idx, p.avatar_url,
             p.xp
        from profiles p where p.id = paired.a;
    return;
  end if;

  -- Whoever has waited longest, near this level, and still here, with no
  -- block or mute either way — a mute in a live match would be offering each
  -- of them the other. Two who have met before meet again: two people
  -- searching at the same moment are a match whoever they are, and every one
  -- of those matches counts (settle_duel).
  select q.* into waiting from live_queue q
    join profiles p on p.id = q.profile_id
   where q.profile_id <> me.id
     and q.seen_at > now() - interval '5 seconds'
     -- Close in level first, wider the longer either of them has waited:
     -- the nearest opponent when there is one, and a match rather than a
     -- recorded set when there is not.
     and abs(q.level - my_level) <= greatest(
           live_reach(my_wait),
           live_reach(extract(epoch from now() - q.joined_at)))
     and not exists (
       select 1 from blocks bl
        where (bl.blocker = me.id and bl.blocked = p.id)
           or (bl.blocker = p.id and bl.blocked = me.id)
     )
     and not exists (
       select 1 from mutes mu
        where (mu.muter = me.id and mu.muted = p.id)
           or (mu.muter = p.id and mu.muted = me.id)
     )
   order by abs(q.level - my_level), q.joined_at
   limit 1;

  if waiting.profile_id is not null then
    delete from live_queue
     where live_queue.profile_id in (me.id, waiting.profile_id);
    insert into live_matches (ranked, a, b, status, ready_by)
    values (true, me.id, waiting.profile_id, 'ready',
            now() + interval '75 seconds')
    returning * into paired;
    return query
      select paired.id, p.id, p.username, p.tier_idx, p.div_idx, p.avatar_url,
             p.xp
        from profiles p where p.id = waiting.profile_id;
    return;
  end if;

  -- Nobody yet: wait here to be found.
  insert into live_queue (profile_id, level)
  values (me.id, my_level)
  on conflict (profile_id) do update
    set seen_at = now(), level = excluded.level;
end;
$$;

-- The search gave up at fifteen seconds. Also calls off a pairing that landed
-- in the moment between the last check and giving up: the other phone is told
-- by `live_match_state` and searches again, rather than waiting for somebody
-- who has already gone to race a saved set.
create or replace function leave_live_queue()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtext('outrepd.live_queue'));
  delete from live_queue where live_queue.profile_id = auth.uid();
  update live_matches lm set status = 'cancelled'
   where lm.b = auth.uid() and lm.ranked and lm.status = 'ready'
     and not lm.b_ready;
end;
$$;

-- ─────────────────────────────── friend: the invite ────────────────────────────

-- Asks one friend to go live now. Any earlier invite of the caller's that is
-- still open is withdrawn: one invite at a time.
create or replace function invite_live(friend_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me profiles;
  new_id uuid;
begin
  perform require_pro();
  select * into me from profiles where id = auth.uid();
  if me is null then
    raise exception 'no profile for this account';
  end if;
  if not exists (
    select 1 from friendships f
     where f.accepted_at is not null
       and ((f.requester = me.id and f.addressee = friend_id)
         or (f.addressee = me.id and f.requester = friend_id))
  ) then
    raise exception 'only a friend can be invited live';
  end if;
  if exists (
    select 1 from blocks bl
     where (bl.blocker = me.id and bl.blocked = friend_id)
        or (bl.blocker = friend_id and bl.blocked = me.id)
  ) then
    raise exception 'only a friend can be invited live';
  end if;

  -- Every invite is a push on their phone, and cancelling one and sending
  -- another is a second: three to one friend in ten minutes, six in all.
  if not within_rate('live_invite_to', interval '10 minutes', 3, friend_id)
     or not within_rate('live_invite', interval '10 minutes', 6) then
    raise exception 'too many invites, wait a few minutes';
  end if;

  update live_matches lm set status = 'cancelled'
   where lm.a = me.id and lm.status = 'invited';

  insert into live_matches (ranked, a, b, status, expires_at)
  values (false, me.id, friend_id, 'invited', now() + interval '60 seconds')
  returning id into new_id;

  -- A notice, and with it a push (push.sql): the friend may not have the
  -- app open, which is the whole reason there is a minute to answer in.
  -- Unless they turned these off — the invite still shows in the app.
  if exists (
    select 1 from profiles p where p.id = friend_id and p.notify_live_invite
  ) then
    insert into notifications (profile_id, kind, actor, actor_name)
    values (friend_id, 'live_invite', me.id, coalesce(me.username, ''));
  end if;

  return new_id;
end;
$$;

-- Invites waiting on the caller, newest first, with how long each has left.
-- A friend's invite is friendly; a rematch is whatever the match before it
-- was, so the one being asked is told which. Dropped first because `ranked`
-- was added after the other columns.
drop function if exists my_live_invites();
create or replace function my_live_invites()
returns table (
  match_id uuid,
  from_id uuid,
  from_name text,
  from_tier int,
  from_div int,
  expires_in_ms int,
  ranked boolean,
  from_avatar text,
  from_xp int
)
language sql
security definer
set search_path = public
stable
as $$
  select lm.id, p.id, p.username, p.tier_idx, p.div_idx,
         greatest(0, (extract(epoch from lm.expires_at - now()) * 1000)::int),
         lm.ranked, p.avatar_url, p.xp
    from live_matches lm
    join profiles p on p.id = lm.a
   where lm.b = auth.uid()
     and lm.status = 'invited'
     and lm.expires_at > now()
   order by lm.created_at desc;
$$;

-- Yes or no to an invite. Answers with what the invite is now: 'ready' once
-- accepted, otherwise why it could not be.
create or replace function answer_live_invite(invite uuid, accept boolean)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
begin
  if accept then
    perform require_pro();
  end if;
  select * into m from live_matches lm
   where lm.id = invite and lm.b = auth.uid()
   for update;
  if m.id is null then
    return 'gone';
  end if;
  if m.status <> 'invited' then
    return m.status;
  end if;
  if m.expires_at <= now() then
    update live_matches lm set status = 'expired' where lm.id = m.id;
    return 'expired';
  end if;

  if accept then
    update live_matches lm
       set status = 'ready', ready_by = now() + interval '75 seconds'
     where lm.id = m.id;
    return 'ready';
  end if;
  update live_matches lm set status = 'declined' where lm.id = m.id;
  return 'declined';
end;
$$;

-- The one who asked, changing their mind before it was answered.
create or replace function cancel_live_invite(invite uuid)
returns void
language sql
security definer
set search_path = public
as $$
  update live_matches lm set status = 'cancelled'
   where lm.id = invite and lm.a = auth.uid() and lm.status = 'invited';
$$;

-- ──────────────────────────────── both: the rematch ────────────────────────────

-- Another one, straight after a live match, from the result screen: either of
-- the two asks, and when the other asks too it starts. Not only for friends —
-- the two were just on camera together — and as ranked as the match before
-- it.
--
-- Answers with the rematch and where it stands: 'invited' while waiting on
-- the other, 'ready' once both have asked.
create or replace function rematch_live(after uuid)
returns table (match_id uuid, match_status text, is_ranked boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  prev live_matches;
  them uuid;
  theirs live_matches;
  mine live_matches;
  pays boolean;
  new_id uuid;
begin
  perform require_pro();
  -- Both pressing at once would otherwise send two invites past each other,
  -- each waiting on the other. One at a time, the second finds the first.
  perform pg_advisory_xact_lock(hashtext('rematch:' || after::text));

  select * into prev from live_matches lm
   where lm.id = after and me in (lm.a, lm.b);
  if prev.id is null or prev.status <> 'done' then
    raise exception 'no finished live match to rematch';
  end if;
  -- Asked for on the result screen, not days later.
  if coalesce(prev.starts_at, prev.created_at) < now() - interval '10 minutes' then
    raise exception 'that match was too long ago to rematch';
  end if;
  them := case when prev.a = me then prev.b else prev.a end;
  if exists (
    select 1 from blocks bl
     where (bl.blocker = me and bl.blocked = them)
        or (bl.blocker = them and bl.blocked = me)
  ) then
    raise exception 'no rematch with this lifter';
  end if;
  -- They have left the result screen: nobody is there to say yes.
  if (case when prev.a = me then prev.b_left_result else prev.a_left_result end)
       is not null then
    raise exception 'they left';
  end if;

  -- They asked first: this is the yes.
  select * into theirs from live_matches lm
   where lm.rematch_of = after and lm.a = them and lm.b = me
     and lm.status = 'invited' and lm.expires_at > now()
   for update;
  if theirs.id is not null then
    update live_matches lm
       set status = 'ready', ready_by = now() + interval '75 seconds'
     where lm.id = theirs.id;
    return query select theirs.id, 'ready'::text, theirs.ranked;
    return;
  end if;

  -- Asked already: the same rematch, not a second one.
  select * into mine from live_matches lm
   where lm.rematch_of = after and lm.a = me
     and lm.status in ('invited', 'ready', 'live')
     and (lm.status <> 'invited' or lm.expires_at > now());
  if mine.id is not null then
    return query select mine.id, mine.status, mine.ranked;
    return;
  end if;

  if not within_rate('live_rematch', interval '10 minutes', 6) then
    raise exception 'too many rematches, wait a few minutes';
  end if;

  -- Ranked if the match before was: a friend's match stays friendly, a
  -- match the search found pays again.
  pays := prev.ranked;

  update live_matches lm set status = 'cancelled'
   where lm.a = me and lm.status = 'invited';
  insert into live_matches (ranked, a, b, status, expires_at, rematch_of)
  values (pays, me, them, 'invited', now() + interval '30 seconds', after)
  returning id into new_id;
  return query select new_id, 'invited'::text, pays;
end;
$$;

-- The caller is on the result screen of [after], or — with [leaving] — has
-- just left it. Answers where the other one is: 'here', 'waiting' (not on
-- their result screen yet), or 'left' — gone from it, or silent for longer
-- than a phone that is still there ever is, or never arriving long after the
-- round ended.
create or replace function live_result_presence(after uuid, leaving boolean default false)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
  i_am_a boolean;
  their_seen timestamptz;
  their_left timestamptz;
begin
  select * into m from live_matches lm
   where lm.id = after and auth.uid() in (lm.a, lm.b)
   for update;
  if m.id is null then
    raise exception 'no such live match';
  end if;
  i_am_a := m.a = auth.uid();

  if i_am_a then
    update live_matches lm
       set a_result_seen = now(),
           a_left_result = case when leaving then now() else lm.a_left_result end
     where lm.id = m.id;
    their_seen := m.b_result_seen;
    their_left := m.b_left_result;
  else
    update live_matches lm
       set b_result_seen = now(),
           b_left_result = case when leaving then now() else lm.b_left_result end
     where lm.id = m.id;
    their_seen := m.a_result_seen;
    their_left := m.a_left_result;
  end if;

  if their_left is not null then
    return 'left';
  end if;
  if their_seen is not null then
    -- A phone on the result screen says so every couple of seconds.
    return case when their_seen > now() - interval '12 seconds'
                then 'here' else 'left' end;
  end if;
  -- Not there yet: still finishing, or never coming. A minute's round and
  -- forty seconds after it is longer than any phone takes to get there.
  if coalesce(m.starts_at, m.created_at) < now() - interval '100 seconds' then
    return 'left';
  end if;
  return 'waiting';
end;
$$;

-- ─────────────────────────────── both: the match ───────────────────────────────

-- Where a match stands, from the caller's side of it. Also where lapsed
-- invites and pairings are called off: nothing else runs on a timer.
drop function if exists live_match_state(uuid);
create or replace function live_match_state(live uuid)
returns table (
  match_status text,
  is_ranked boolean,
  opponent_id uuid,
  opponent_name text,
  opponent_tier int,
  opponent_div int,
  they_are_ready boolean,
  starts_in_ms int,
  expires_in_ms int,
  their_reps int,
  opponent_avatar text,
  opponent_xp int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
  i_am_a boolean;
begin
  select * into m from live_matches lm
   where lm.id = live and auth.uid() in (lm.a, lm.b)
   for update;
  if m.id is null then
    raise exception 'no such live match';
  end if;
  i_am_a := m.a = auth.uid();

  if m.status = 'invited' and m.expires_at <= now() then
    update live_matches lm set status = 'expired' where lm.id = m.id;
    m.status := 'expired';
  elsif m.status = 'ready' and m.ready_by <= now() then
    -- Paired, and one of them never turned up.
    update live_matches lm set status = 'expired' where lm.id = m.id;
    m.status := 'expired';
  end if;

  return query
    select m.status, m.ranked, p.id, p.username, p.tier_idx, p.div_idx,
           case when i_am_a then m.b_ready else m.a_ready end,
           case when m.starts_at is null then null
                else (extract(epoch from m.starts_at - now()) * 1000)::int end,
           case when m.expires_at is null then null
                else greatest(0, (extract(epoch from m.expires_at - now()) * 1000)::int) end,
           case when i_am_a then m.b_reps else m.a_reps end,
           p.avatar_url, p.xp
      from profiles p
     where p.id = case when i_am_a then m.b else m.a end;
end;
$$;

-- The caller is on the match screen. When both are, the round gets its
-- start: ten seconds out, for both to get down while both phones count to
-- it, and then it starts for both at once whether or not they are down.
-- Returns how far away that start is, or null while the other is not there.
create or replace function live_ready(live uuid)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
begin
  select * into m from live_matches lm
   where lm.id = live and auth.uid() in (lm.a, lm.b)
   for update;
  if m.id is null then
    raise exception 'no such live match';
  end if;
  if m.status not in ('ready', 'live') then
    return null;
  end if;

  if m.a = auth.uid() then
    m.a_ready := true;
  else
    m.b_ready := true;
  end if;
  if m.a_ready and m.b_ready and m.starts_at is null then
    m.starts_at := now() + interval '10 seconds';
    m.status := 'live';
  end if;

  update live_matches lm
     set a_ready = m.a_ready, b_ready = m.b_ready,
         starts_at = m.starts_at, status = m.status
   where lm.id = m.id;

  if m.starts_at is null then
    return null;
  end if;
  return (extract(epoch from m.starts_at - now()) * 1000)::int;
end;
$$;

-- The caller's count so far. Only kept for a phone that drops out: the live
-- display travels phone to phone, and this is what is left if one vanishes.
create or replace function report_live_count(live uuid, reps_now int)
returns void
language sql
security definer
set search_path = public
as $$
  update live_matches lm set
    a_reps = case when lm.a = auth.uid() then least(greatest(reps_now, 0), 300) else lm.a_reps end,
    a_seen = case when lm.a = auth.uid() then now() else lm.a_seen end,
    b_reps = case when lm.b = auth.uid() then least(greatest(reps_now, 0), 300) else lm.b_reps end,
    b_seen = case when lm.b = auth.uid() then now() else lm.b_seen end
   where lm.id = live and lm.status = 'live' and auth.uid() in (lm.a, lm.b);
$$;

-- The three below answer with the same columns, and `result_ranked` was added
-- after the rest; a function's result columns cannot change in place.
drop function if exists live_outcome(live_matches);
drop function if exists finish_live_match(uuid, int, int, real, boolean, int, boolean, int[]);
drop function if exists live_match_result(uuid);

-- A finished match, from the caller's side: `settle_duel`'s answer for
-- whoever settled it, read back off the duel and the account for the other.
create or replace function live_outcome(m live_matches)
returns table (
  is_settled boolean,
  result_duel uuid,
  result_won boolean,
  result_lp_delta int,
  result_tier int,
  result_div int,
  result_lp int,
  result_wins int,
  result_losses int,
  result_win_streak int,
  result_best_streak int,
  result_placements_done int,
  result_placement_wins int,
  result_their_reps int,
  -- Whether it moved the ladder: see settle_duel's was_ranked.
  result_ranked boolean
)
language sql
security definer
set search_path = public
stable
as $$
  select true, d.id, d.winner = p.id,
         case when d.challenger = p.id then d.lp_challenger else d.lp_defender end,
         p.tier_idx, p.div_idx, p.lp, p.wins, p.losses, p.win_streak,
         p.best_streak, p.placements_done, p.placement_wins,
         (select s.reps from sets s
           where s.id = case when m.a = p.id then m.b_set else m.a_set end),
         d.ranked
    from duels d, profiles p
   where d.id = m.duel and p.id = auth.uid();
$$;

revoke all on function live_outcome(live_matches) from public, anon, authenticated;

-- Settles a match whose two sets are both in, as the caller.
create or replace function settle_live(m live_matches)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  mine uuid := case when m.a = auth.uid() then m.a_set else m.b_set end;
  theirs uuid := case when m.a = auth.uid() then m.b_set else m.a_set end;
  settled record;
begin
  select * into settled from settle_duel(mine, theirs, m.ranked);
  update live_matches lm set status = 'done', duel = settled.duel_id
   where lm.id = m.id;
  -- settle_duel tells the other side they were raced (notify.sql). They were
  -- there, on camera, watching it happen; that notice is for a set raced
  -- while its owner was away.
  delete from notifications n where n.duel_id = settled.duel_id;
end;
$$;

revoke all on function settle_live(live_matches) from public, anon, authenticated;

-- The caller's set, at the end of the round. Settles the match if the other
-- set is already in; otherwise the caller waits on `live_match_result`.
create or replace function finish_live_match(
  live uuid,
  set_reps int,
  set_reps_camera int,
  set_depth real,
  set_confident boolean,
  set_duration_ms int,
  set_gave_up boolean,
  set_rep_times int[]
)
returns table (
  is_settled boolean,
  result_duel uuid,
  result_won boolean,
  result_lp_delta int,
  result_tier int,
  result_div int,
  result_lp int,
  result_wins int,
  result_losses int,
  result_win_streak int,
  result_best_streak int,
  result_placements_done int,
  result_placement_wins int,
  result_their_reps int,
  -- Whether it moved the ladder: see settle_duel's was_ranked.
  result_ranked boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
  i_am_a boolean;
  my_set uuid;
begin
  select * into m from live_matches lm
   where lm.id = live and auth.uid() in (lm.a, lm.b)
   for update;
  if m.id is null then
    raise exception 'no such live match';
  end if;
  if m.starts_at is null then
    raise exception 'this match never started';
  end if;
  i_am_a := m.a = auth.uid();
  my_set := case when i_am_a then m.a_set else m.b_set end;

  -- Once. A phone that lost its connection and sends again, or whose set the
  -- other side already had to stand in for, gets the result and nothing more.
  if my_set is null then
    insert into sets (profile_id, reps, reps_camera, depth, confident,
                      duration_ms, gave_up, rep_times, live_match)
    values (auth.uid(), set_reps, set_reps_camera, set_depth, set_confident,
            set_duration_ms, set_gave_up, coalesce(set_rep_times, '{}'), m.id)
    returning id into my_set;
    if i_am_a then
      m.a_set := my_set;
      m.a_reps := set_reps;
    else
      m.b_set := my_set;
      m.b_reps := set_reps;
    end if;
    update live_matches lm
       set a_set = m.a_set, b_set = m.b_set,
           a_reps = m.a_reps, b_reps = m.b_reps
     where lm.id = m.id;
  end if;

  if m.duel is null and m.a_set is not null and m.b_set is not null then
    perform settle_live(m);
    select * into m from live_matches lm where lm.id = live;
  end if;

  if m.duel is null then
    return query select false, null::uuid, null::boolean, null::int, null::int,
                        null::int, null::int, null::int, null::int, null::int,
                        null::int, null::int, null::int, null::int,
                        null::boolean;
    return;
  end if;
  return query select * from live_outcome(m);
end;
$$;

-- For the one who finished first. The result once there is one; and once the
-- other side is long overdue — the round, plus forty seconds to send — the
-- match is settled on the last count their phone reported, which is the rule
-- the screen showed while it ran: their number froze, the clock did not.
create or replace function live_match_result(live uuid)
returns table (
  is_settled boolean,
  result_duel uuid,
  result_won boolean,
  result_lp_delta int,
  result_tier int,
  result_div int,
  result_lp int,
  result_wins int,
  result_losses int,
  result_win_streak int,
  result_best_streak int,
  result_placements_done int,
  result_placement_wins int,
  result_their_reps int,
  -- Whether it moved the ladder: see settle_duel's was_ranked.
  result_ranked boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  m live_matches;
  i_am_a boolean;
  stand_in uuid;
begin
  select * into m from live_matches lm
   where lm.id = live and auth.uid() in (lm.a, lm.b)
   for update;
  if m.id is null then
    raise exception 'no such live match';
  end if;
  i_am_a := m.a = auth.uid();

  if m.duel is null
     and (case when i_am_a then m.a_set else m.b_set end) is not null
     and (case when i_am_a then m.b_set else m.a_set end) is null
     and m.starts_at + interval '100 seconds' < now() then
    -- At most what a minute holds (sets_reps_fit_the_time, schema.sql): the
    -- count came from their phone, and the stand-in is stored as a minute.
    insert into sets (profile_id, reps, reps_camera, depth, confident,
                      duration_ms, gave_up, rep_times, live_match)
    values (case when i_am_a then m.b else m.a end,
            least(case when i_am_a then m.b_reps else m.a_reps end, 200),
            least(case when i_am_a then m.b_reps else m.a_reps end, 200),
            0, false, 60000, false, '{}', m.id)
    returning id into stand_in;
    if i_am_a then
      m.b_set := stand_in;
    else
      m.a_set := stand_in;
    end if;
    update live_matches lm set a_set = m.a_set, b_set = m.b_set
     where lm.id = m.id;
    perform settle_live(m);
    select * into m from live_matches lm where lm.id = live;
  end if;

  if m.duel is null then
    return query select false, null::uuid, null::boolean, null::int, null::int,
                        null::int, null::int, null::int, null::int, null::int,
                        null::int, null::int, null::int, null::int,
                        null::boolean;
    return;
  end if;
  return query select * from live_outcome(m);
end;
$$;

revoke all on function find_live_opponent() from public, anon;
grant execute on function find_live_opponent() to authenticated;
