-- ========================================================================
-- testers.sql
-- ========================================================================

-- ─────────────────────────────── closed-test testers ─────────────────────────
--
-- Testers get Pro without buying it. A test purchase on Google Play renews
-- every few minutes and emails a receipt each time, then lapses and puts the
-- paywall back — so a tester who subscribed with the test card was mailed all
-- day and asked to pay again by evening. Instead their emails go on a list,
-- and an account that signs up with one is given Pro by RevenueCat, as a
-- promotional grant: no purchase, no receipts, nothing to renew.
--
-- Two ways an account and the list meet, and either hands the account to the
-- revenuecat-webhook function, which makes the grant:
--   - somebody types a listed email at sign-up. Caught when the email is
--     typed, before the code is, so the grant is in place by the time the
--     paywall would open;
--   - an email is added to the list after its owner already signed up.
--
-- The function checks the list itself, from the account's own record, and
-- grants each account once; whoever calls it can do nothing else with it.
-- Adding and removing testers: supabase/switches.sql.

create table if not exists beta_testers (
  email    text primary key check (email = lower(trim(email))),
  added_at timestamptz not null default now()
);
alter table beta_testers enable row level security;

-- Each account given its pass, so it is given once.
create table if not exists beta_tester_grants (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  email      text not null,
  granted_at timestamptz not null default now()
);
alter table beta_tester_grants enable row level security;

create or replace function grant_tester_pro(for_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform net.http_post(
    url := 'https://pzhdakzjbjyxhspymjhb.supabase.co/functions/v1/revenuecat-webhook',
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body := jsonb_build_object('tester', for_user)
  );
end;
$$;

-- On auth.users, so it runs inside every sign-up and sign-in. Nothing in it
-- may ever fail one: every error is caught and only warned about.
create or replace function tester_signed_up()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    if exists (
         select 1 from beta_testers b
          where b.email in (lower(trim(coalesce(new.email, ''))),
                            lower(trim(coalesce(new.email_change, ''))))
       )
       and not exists (
         select 1 from beta_tester_grants g where g.user_id = new.id
       ) then
      perform grant_tester_pro(new.id);
    end if;
  exception when others then
    raise warning 'tester pass not queued: %', sqlerrm;
  end;
  return new;
end;
$$;

drop trigger if exists tester_signed_up on auth.users;
create trigger tester_signed_up
  after insert or update of email, email_change on auth.users
  for each row execute function tester_signed_up();

create or replace function tester_added()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  account uuid;
begin
  begin
    for account in
      select u.id from auth.users u
       where lower(trim(u.email)) = new.email
         and not exists (select 1 from beta_tester_grants g where g.user_id = u.id)
    loop
      perform grant_tester_pro(account);
    end loop;
  exception when others then
    raise warning 'tester pass not queued: %', sqlerrm;
  end;
  return new;
end;
$$;

drop trigger if exists tester_added on beta_testers;
create trigger tester_added
  after insert on beta_testers
  for each row execute function tester_added();

revoke all on function grant_tester_pro(uuid) from public, anon, authenticated;
revoke all on function tester_signed_up() from public, anon, authenticated;
revoke all on function tester_added() from public, anon, authenticated;

-- ========================================================================
-- adventure.sql
-- ========================================================================

-- ─────────────────────────────── adventure ────────────────────────────────────
--
-- The adventure's progress on the account: the best stars won on each of its
-- hundred and forty levels, so a new phone or a reinstall picks up where the
-- last one left off.
--
-- Nothing anybody else sees depends on it — no board, no rank — so the server
-- does not referee the stars; it only keeps them, and never lets one phone
-- take stars off another: a save keeps the best of what was held and what was
-- sent, level by level.

create table if not exists adventure_progress (
  profile_id uuid primary key references profiles on delete cascade,
  -- One per level from the first, 0 to 3; 0 is a level not won.
  stars      smallint[] not null default '{}',
  updated_at timestamptz not null default now(),
  constraint adventure_progress_levels check (cardinality(stars) <= 140)
);

-- Row level security and no policy at all: the two functions below are the
-- only way in, for reading and for writing.
alter table adventure_progress enable row level security;

-- This account's stars, or none.
create or replace function my_adventure()
returns smallint[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select stars from adventure_progress where profile_id = auth.uid()),
    '{}'::smallint[]
  );
$$;

-- Saves [new_stars] onto this account, the best of them and what it already
-- held on every level, and hands back what it now holds.
create or replace function save_adventure(new_stars smallint[])
returns smallint[]
language plpgsql
security definer
set search_path = public
as $$
declare
  held smallint[];
  merged smallint[] := '{}';
  levels int;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  if new_stars is null or cardinality(new_stars) > 140 then
    raise exception 'not an adventure';
  end if;
  -- A save follows a won fight, a minute each at most; a phone sending more
  -- than this is not a phone lifting.
  if not within_rate('adventure', interval '1 hour', 240) then
    raise exception 'too often';
  end if;

  select stars into held
    from adventure_progress
   where profile_id = auth.uid()
     for update;
  held := coalesce(held, '{}');

  levels := greatest(cardinality(held), cardinality(new_stars));
  for i in 1 .. levels loop
    merged := merged || least(3, greatest(
      0,
      coalesce(held[i], 0),
      coalesce(new_stars[i], 0)
    ))::smallint;
  end loop;

  insert into adventure_progress (profile_id, stars, updated_at)
  values (auth.uid(), merged, now())
  on conflict (profile_id)
  do update set stars = excluded.stars, updated_at = excluded.updated_at;
  return merged;
end;
$$;

revoke all on function my_adventure() from public, anon;
grant execute on function my_adventure() to authenticated;
revoke all on function save_adventure(smallint[]) from public, anon;
grant execute on function save_adventure(smallint[]) to authenticated;

-- ─────────────────────────────── rewards ──────────────────────────────────────
--
-- The titles this lifter has earned and the one they wear, with the tallies
-- and the training streak the titles are earned by (lib/rewards.dart). They
-- lived on the phone alone, so a new phone, or one handed between accounts,
-- started them all again (the user, 2026-10-29). Nobody else's screen
-- depends on them past the worn title, which profiles carries already, so
-- the server keeps them rather than referees them, the way it keeps the
-- adventure's stars — and never lets one phone take anything from another:
-- a save keeps every title either side has, the larger of each tally, and
-- the streak of whichever side trained last.

create table if not exists rewards_progress (
  profile_id uuid primary key references profiles on delete cascade,
  state      jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  constraint rewards_progress_object check (jsonb_typeof(state) = 'object'),
  constraint rewards_progress_size check (pg_column_size(state) <= 16384)
);

-- Row level security and no policy: the two functions below are the way in.
alter table rewards_progress enable row level security;

-- A whole number at [k] in [j], or 0 for anything else: what a phone sends
-- is never trusted to be the shape it should be.
create or replace function rewards_int(j jsonb, k text)
returns bigint
language sql
immutable
set search_path = public
as $$
  select case when jsonb_typeof(j -> k) = 'number'
              then greatest(0, least((j ->> k)::numeric, 9e15))::bigint
              else 0 end;
$$;

-- Two copies made one. Titles are ids as lib/rewards.dart names them.
create or replace function rewards_merge(a jsonb, b jsonb)
returns jsonb
language sql
immutable
set search_path = public
as $$
  with later as (
    select case when rewards_int(b, 'lastSession') >= rewards_int(a, 'lastSession')
                then b else a end as s
  ),
  titles as (
    select distinct e #>> '{}' as id
      from (
        select jsonb_array_elements(case when jsonb_typeof(a -> 'earned') = 'array'
                                         then a -> 'earned' else '[]'::jsonb end) as e
        union all
        select jsonb_array_elements(case when jsonb_typeof(b -> 'earned') = 'array'
                                         then b -> 'earned' else '[]'::jsonb end)
      ) every_title
     where jsonb_typeof(e) = 'string'
       and (e #>> '{}') ~ '^[a-z0-9_]{1,40}$'
     limit 200
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'streak',        (select rewards_int(s, 'streak') from later),
    'restUsed',      (select rewards_int(s, 'restUsed') from later),
    'perfectDayRun', (select rewards_int(s, 'perfectDayRun') from later),
    'lastSession',   nullif((select rewards_int(s, 'lastSession') from later), 0),
    'wearing',       (select case when (s ->> 'wearing') ~ '^[a-z0-9_]{1,40}$'
                                  then s ->> 'wearing' end from later),
    'bestStreak',    greatest(rewards_int(a, 'bestStreak'), rewards_int(b, 'bestStreak')),
    'cleanSets',     greatest(rewards_int(a, 'cleanSets'), rewards_int(b, 'cleanSets')),
    'earlySessions', greatest(rewards_int(a, 'earlySessions'), rewards_int(b, 'earlySessions')),
    'lateSessions',  greatest(rewards_int(a, 'lateSessions'), rewards_int(b, 'lateSessions')),
    'perfectWeeks',  greatest(rewards_int(a, 'perfectWeeks'), rewards_int(b, 'perfectWeeks')),
    'earned',        coalesce((select jsonb_agg(id order by id) from titles), '[]'::jsonb)
  ));
$$;

-- What the account holds; an empty object for an account with nothing yet.
create or replace function my_rewards()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select r.state from rewards_progress r where r.profile_id = auth.uid()),
    '{}'::jsonb
  );
$$;

-- This phone's copy, merged into the account's; the merged one back, for the
-- phone to take in what another phone added.
create or replace function save_rewards(new_state jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  held jsonb;
  merged jsonb;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  if new_state is null or jsonb_typeof(new_state) <> 'object'
     or pg_column_size(new_state) > 16384 then
    raise exception 'not a rewards copy';
  end if;
  -- A save follows a session or a title worn; a phone saving faster than
  -- that is a loop, and gets the copy held instead.
  if not within_rate('rewards', interval '1 hour', 240) then
    return my_rewards();
  end if;

  select r.state into held from rewards_progress r where r.profile_id = auth.uid();
  merged := rewards_merge(coalesce(held, '{}'::jsonb), new_state);

  insert into rewards_progress (profile_id, state, updated_at)
  values (auth.uid(), merged, now())
  on conflict (profile_id)
  do update set state = excluded.state, updated_at = excluded.updated_at;
  return merged;
end;
$$;

revoke all on function rewards_int(jsonb, text) from public, anon, authenticated;
revoke all on function rewards_merge(jsonb, jsonb) from public, anon, authenticated;
revoke all on function my_rewards() from public, anon;
grant execute on function my_rewards() to authenticated;
revoke all on function save_rewards(jsonb) from public, anon;
grant execute on function save_rewards(jsonb) to authenticated;

-- ========================================================================
-- account.sql
-- ========================================================================

-- OUTREPD — the two things a person is entitled to do with their account.
--
-- Take everything with them, and leave.
--
-- Both are irreversible and both are theirs alone: every query below is
-- scoped by `auth.uid()` and nothing takes an account id as an argument,
-- because a function that deletes the account you name is a function that
-- deletes anybody's.

-- Everything the server holds about the caller, in one object.
--
-- Read here rather than assembled on the phone so the answer is the
-- database's own, and so the export and the delete agree about what "your
-- data" means — the same tables appear in both.
--
-- What is *not* in here is as much the point as what is. There are no pose
-- landmarks and no video: pose detection runs on the phone and the frames
-- never leave it, so there is nothing on any server to hand back.
-- Security definer: a friend's or a blocked account's name is read off a
-- profile the caller cannot read directly. Every part is scoped to auth.uid().
create or replace function my_data()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile', (
      select to_jsonb(p) - 'id' from profiles p where p.id = auth.uid()
    ),
    'sets', coalesce((
      select jsonb_agg(to_jsonb(s) - 'profile_id' order by s.created_at)
        from sets s where s.profile_id = auth.uid()
    ), '[]'::jsonb),
    'duels', coalesce((
      select jsonb_agg(to_jsonb(d) order by d.created_at)
        from duels d
       where d.challenger = auth.uid() or d.defender = auth.uid()
    ), '[]'::jsonb),
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object(
               'username', p.username,
               'since', f.accepted_at,
               'you_asked', f.requester = auth.uid()))
        from friendships f
        join profiles p
          on p.id = case when f.requester = auth.uid()
                         then f.addressee else f.requester end
       where f.requester = auth.uid() or f.addressee = auth.uid()
    ), '[]'::jsonb),
    'blocked', coalesce((
      select jsonb_agg(jsonb_build_object(
               'username', p.username, 'at', b.created_at))
        from blocks b join profiles p on p.id = b.blocked
       where b.blocker = auth.uid()
    ), '[]'::jsonb),
    'notifications', coalesce((
      select jsonb_agg(to_jsonb(n) - 'profile_id' order by n.created_at)
        from notifications n where n.profile_id = auth.uid()
    ), '[]'::jsonb),
    'live_matches', coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at)
        from live_matches m where m.a = auth.uid() or m.b = auth.uid()
    ), '[]'::jsonb),
    'month_awards', coalesce((
      select jsonb_agg(to_jsonb(w) - 'profile_id' order by w.season)
        from season_awards w where w.profile_id = auth.uid()
    ), '[]'::jsonb),
    'adventure_stars', (
      select to_jsonb(a.stars)
        from adventure_progress a where a.profile_id = auth.uid()
    ),
    'rewards', (
      select r.state from rewards_progress r where r.profile_id = auth.uid()
    ),
    'reports_filed', coalesce((
      select count(*) from reports r where r.reporter = auth.uid()
    ), 0)
  );
$$;

-- Whether the export may be emailed once more today. Asked by the
-- email-my-data function, with the caller's own sign-in, before it sends:
-- three a day is plenty for anybody's own copy, and the function's sender is
-- this project's, which mail services judge by how much it sends.
create or replace function claim_data_export()
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  return within_rate('data_export', interval '1 day', 3);
end;
$$;

-- What is about to be lost, for the screen that asks whether you are sure.
--
-- The same numbers the profile shows, fetched again rather than passed in:
-- a confirmation screen quoting figures the client supplied is a
-- confirmation of whatever the client felt like saying.
create or replace function my_account_summary()
returns table (
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  total_reps int,
  best_set int,
  friends int
)
language sql
stable
set search_path = public
as $$
  select p.tier_idx, p.div_idx, p.lp, p.placements_done,
         p.total_reps, p.best_set,
         (select count(*)::int from friendships f
           where f.accepted_at is not null
             and (f.requester = p.id or f.addressee = p.id))
    from profiles p
   where p.id = auth.uid();
$$;

-- Delete this account and everything hanging off it.
--
-- One statement: `profiles` cascades from `auth.users`, and sets, duels,
-- friendships, blocks and notifications all cascade from `profiles`. Deleting
-- the auth user is therefore the whole of it, and doing it in one place means
-- there is no list of tables to keep in step with the schema.
--
-- Duels go too: `duels.challenger` and `duels.defender` cascade, so the
-- opponent loses the row from their history. The LP it paid them stays, since
-- that lives on their own profile.
create or replace function delete_my_account()
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

-- ─────────────────────────────── renaming ─────────────────────────────────────

-- Whether a name is free, checked before the rename screen shows it as such.
-- Case-insensitive: "Mokhtar" and "mokhtar" reading as different accounts
-- would be a bug nobody could explain.
create or replace function username_available(name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not exists (
    select 1 from profiles where lower(username) = lower(trim(name))
  );
$$;

-- Renames this account.
--
-- As a guest — no confirmed email yet — as often as it likes. The name is
-- chosen on the sign-up screen, before the code has been typed, and somebody
-- who goes back to fix a typo, or because their email was already taken,
-- has to be able to choose again: when the first try counted as the one
-- rename, the second was quietly refused and the account kept a name its
-- owner had already changed their mind about.
--
-- Once the email is confirmed, a name can be changed again fourteen days after
-- it was last chosen (username_changed_at): often enough to fix a name somebody
-- regrets, not so often that nobody on a board knows who anybody is. The app
-- reads the same column to say on which day. Re-checks availability itself —
-- the gap between the screen's own check and this call is exactly long enough
-- for somebody else to take it.
--
-- Letters and digits only, four characters minimum. A tag another lifter
-- reads off a leaderboard or types into a search box, not a display name —
-- no spaces or punctuation to type around, no length short enough to be
-- somebody else by accident.
--
-- Security definer: whether a name is taken means looking at everybody's,
-- and a lifter can only read their own row; and whether the email is
-- confirmed is in auth.users. It writes only the caller's row.
create or replace function set_my_username(new_name text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  cleaned text := trim(new_name);
  confirmed boolean;
begin
  if auth.uid() is null then
    return 'invalid';
  end if;

  select coalesce(u.email, '') <> '' and u.email_confirmed_at is not null
    into confirmed
    from auth.users u where u.id = auth.uid();

  if coalesce(confirmed, false) and exists (
    select 1 from profiles
     where id = auth.uid()
       and username_changed_at > now() - interval '14 days'
  ) then
    return 'already_changed';
  end if;

  -- Free as a guest, but not endless: renaming in a loop is holding names.
  if not within_rate('rename', interval '1 hour', 30) then
    return 'too_often';
  end if;

  -- Letters, numbers and underscores, the way a handle is usually written
  -- (iron_mike), with at least one letter or number among them. The same
  -- characters the guard on a new profile has always allowed; this was the
  -- one place that left the underscore out.
  if char_length(cleaned) < 4 or char_length(cleaned) > 20
     or cleaned !~ '^[A-Za-z0-9_]+$'
     or cleaned !~ '[A-Za-z0-9]' then
    return 'invalid';
  end if;

  if username_not_allowed(cleaned) then
    return 'not_allowed';
  end if;

  if exists (
    select 1 from profiles
     where lower(username) = lower(cleaned) and id <> auth.uid()
  ) then
    return 'taken';
  end if;

  -- The profiles guard refuses a username written any other way.
  perform set_config('outrepd.renaming', 'on', true);
  update profiles
     set username = cleaned, username_changed_at = now()
   where id = auth.uid();
  perform set_config('outrepd.renaming', 'off', true);
  return 'ok';
end;
$$;

-- The country this lifter chooses, by its two-letter code. Free while the
-- account is a guest, as the name is; once it has a confirmed email, once
-- every fourteen days, for the same reason as the name — the country board
-- is one a lifter could hop between to sit on top of a small one.
create or replace function set_my_country(new_country text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  code text := upper(trim(coalesce(new_country, '')));
  confirmed boolean;
begin
  if auth.uid() is null or code !~ '^[A-Z]{2}$' then
    return 'invalid';
  end if;

  select coalesce(u.email, '') <> '' and u.email_confirmed_at is not null
    into confirmed
    from auth.users u where u.id = auth.uid();

  if coalesce(confirmed, false) and exists (
    select 1 from profiles
     where id = auth.uid()
       and country_changed_at > now() - interval '14 days'
  ) then
    return 'too_soon';
  end if;

  if not within_rate('country', interval '1 hour', 30) then
    return 'too_often';
  end if;

  -- The guard on profiles refuses a country written any other way. The
  -- fourteen days start from a choice made with a confirmed account, so a
  -- guest who picks one on the way to signing up can still fix it after.
  perform set_config('outrepd.recountry', 'on', true);
  update profiles
     set country = code,
         country_changed_at = case
           when coalesce(confirmed, false) then now()
           else country_changed_at
         end
   where id = auth.uid();
  perform set_config('outrepd.recountry', 'off', true);
  return 'ok';
end;
$$;

revoke all on function set_my_country(text) from public, anon;
grant execute on function set_my_country(text) to authenticated;

-- ─────────────────────────────── the days ───────────────────────────────────
--
-- This lifter's push-ups day by day, every set they uploaded — ranked, live,
-- a friend's, practice, the adventure — summed in their own days:
-- [tz_minutes] is their clock's offset from UTC. For a phone that has not
-- kept them: a new one, or the same one signed out and back in, which
-- started its week, its streak and today's goal from nothing (2026-10-29).
create or replace function my_days(tz_minutes int default 0, last_days int default 60)
returns table (day date, reps int)
language sql
stable
security definer
set search_path = public
as $$
  select ((s.created_at at time zone 'UTC')
            + make_interval(mins => greatest(-840, least(840, tz_minutes))))::date,
         sum(s.reps)::int
    from sets s
   where s.profile_id = auth.uid()
     and s.created_at > now()
           - make_interval(days => greatest(1, least(400, last_days)))
   group by 1
   order by 1;
$$;

revoke all on function my_days(int, int) from public, anon;
grant execute on function my_days(int, int) to authenticated;

revoke all on function my_data() from public;
grant execute on function my_data() to authenticated;
revoke all on function claim_data_export() from public, anon;
grant execute on function claim_data_export() to authenticated;
revoke all on function my_account_summary() from public;
grant execute on function my_account_summary() to authenticated;
revoke all on function delete_my_account() from public;
grant execute on function delete_my_account() to authenticated;
revoke all on function username_available(text) from public;
grant execute on function username_available(text) to authenticated;
revoke all on function set_my_username(text) from public;
grant execute on function set_my_username(text) to authenticated;

-- ========================================================================
-- lockdown.sql
-- ========================================================================

-- ───────────────────────── what a signed-out caller may do ───────────────────
--
-- Runs last, after every table and function exists.
--
-- Supabase grants every new function in `public` to anon and authenticated
-- by name — its default privileges — so the `revoke … from public` in the
-- files before this left anon, a request carrying no session at all, able
-- to call all of them. Most stop there, on a null auth.uid(); a few did not
-- need one to hand something back: a profile, a recorded set, the boards,
-- whether a username is taken.
--
-- Nobody uses the app signed out. A guest has an anonymous session, which is
-- `authenticated`, not anon. The one thing meant for whoever a link reaches
-- is the share card the website draws at /u/<username>.

--
-- From PUBLIC as well: Postgres itself lets PUBLIC — every role, anon among
-- them — run any new function, on top of Supabase's grants. Signed-in
-- callers keep what they had: Supabase granted authenticated each function
-- by name, and the ones taken from authenticated on purpose above (the rate
-- limiter, settling a live match) stay taken.
--
-- This file runs on every install, after everything else, so a function
-- added later is closed the next time install.sql is pasted.
revoke execute on all functions in schema public from public, anon;
alter default privileges in schema public revoke execute on functions from anon;
grant execute on function public_lifter_card(text) to anon;

-- The tables, the same way. Every one has row level security and no policy
-- names anon, so anon already read and wrote nothing; this takes the
-- privilege itself away, so a table added later and given no policy yet is
-- not the exception.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
